INSERT INTO `course` VALUES (5,'CP005','悯农（其二）','李绅','五言古诗','二年级','cloud://cloudbase-d6g5mlt4tbaa32ec2.636c-cloudbase-d6g5mlt4tbaa32ec2-1432544091/poem_images/5.png','李绅悯农诗之二，春种秋收四海无闲田，农夫犹饿死的现实令人深思。','锄禾日当午，汗滴禾下土。谁知盘中餐，粒粒皆辛苦。','chú hé rì dāng wǔ hàn dī hé xià tǔ shuí zhī pán zhōng cān lì lì jiē xīn kǔ','','','file/5.mp4',230,6,2015,'2026-05-18 16:36:43','2026-05-18 16:36:43'),(7,'CP007','江雪','柳宗元','五言绝句','二年级','cloud://cloudbase-d6g5mlt4tbaa32ec2.636c-cloudbase-d6g5mlt4tbaa32ec2-1432544091/poem_images/7.png','柳宗元被贬永州时所作，千山鸟飞绝万径人踪灭，孤舟独钓寒江雪的遗世独立。','千山鸟飞绝，万径人踪灭。孤舟蓑笠翁，独钓寒江雪。','qiān shān niǎo fēi jué wàn jìng rén zōng miè gū zhōu suō lì wēng dú diào hán jiāng xuě','','','file/7.mp4',168,2,1454,'2026-05-18 14:48:15','2026-05-18 14:48:15'),(8,'CP008','绝句','杜甫','七言绝句','三年级','file/course8.jpg','杜甫成都草堂之作，两个黄鹂一行白鹭，窗前千秋雪门泊万里船，时空交错。','两个黄鹂鸣翠柳，一行白鹭上青天。窗含西岭千秋雪，门泊东吴万里船。','liǎng gè huáng lí míng cuì liǔ yī xíng bái lù shàng qīng tiān chuāng hán xī lǐng qiān qiū xuě mén pō dōng wú wàn lǐ chuán','','','file/8.mp4',188,3,1527,'2026-01-25 10:00:00','2026-05-15 19:13:06'),(12,'CP012','游子吟','孟郊','五言古诗','四年级','file/course12.jpg','孟郊以慈母手中线游子身上衣写尽母爱，谁言寸草心报得三春晖千古传唱。','慈母手中线，游子身上衣。临行密密缝，意恐迟迟归。谁言寸草心，报得三春晖。','cí mǔ shǒu zhōng xiàn yóu zi shēn shàng yī lín xíng mì mì fèng yì kǒng chí chí guī shuí yán cùn cǎo xīn bào dé sān chūn huī','','','file/12.mp4',245,3,2009,'2026-02-01 10:00:00','2026-05-15 19:19:23'),(20,'CP021','江南','汉乐府','乐府诗','一年级',NULL,'汉乐府民歌，采莲时节江南水乡的生动写照，以回旋往复的韵律描绘鱼戏莲叶的欢快画面。','江南可采莲，莲叶何田田。\n鱼戏莲叶间。鱼戏莲叶东，\n鱼戏莲叶西。鱼戏莲叶南，\n鱼戏莲叶北。','jiāng nán kě cǎi lián lián yè hé tián tián|||yú xì lián yè jiān yú xì lián yè dōng|||yú xì lián yè xī yú xì lián yè nán|||yú xì lián yè běi','','',NULL,NULL,NULL,7,NULL,'2026-05-12 18:27:38'),(21,'CP022','敕勒歌','北朝民歌','乐府诗','一年级',NULL,'北朝敕勒族民歌，描绘阴山脚下草原的辽阔壮美，天苍野茫间风吹草低见牛羊。\n----------\n【注解】\n敕勒：种族名。川：平原。阴山：在今内蒙古北部。穹庐：蒙古包。见：同现，显现。\n\n----------\n【译文】\n阴山脚下是敕勒族的大平原。天空像毡帐笼罩四野。天苍苍野茫茫，风吹草低处牛羊时隐时现。','敕勒川，阴山下，\n天似穹庐，笼盖四野。\n天苍苍，野茫茫，\n风吹草低见牛羊。','chì lēi chuān yīn shān xià|||tiān shì qióng lú lóng gài sì yě|||tiān cāng cāng yě máng máng|||fēng chuī cǎo dī jiàn niú yáng','敕勒：种族名。川：平原。阴山：在今内蒙古北部。穹庐：蒙古包。见：同现，显现。\n','阴山脚下是敕勒族的大平原。天空像毡帐笼罩四野。天苍苍野茫茫，风吹草低处牛羊时隐时现。',NULL,NULL,NULL,5,NULL,'2026-05-12 18:27:41'),(22,'CP023','咏鹅','骆宾王','五言古诗','一年级','cloud://cloudbase-d6g5mlt4tbaa32ec2.636c-cloudbase-d6g5mlt4tbaa32ec2-1432544091/poem_images/22.png','骆宾王七岁时即兴所作，以白描手法勾勒白鹅曲项浮水的生动形象，童趣盎然。\n----------\n【注解】\n曲项：弯着脖子。歌：长鸣。拨：划动。\n\n----------\n【译文】\n鹅鹅鹅，面向蓝天伸长脖子歌唱。白色羽毛浮在碧绿水面上，红色脚掌拨动清清的水波。','鹅，鹅，鹅，曲项向天歌。\n白毛浮绿水，红掌拨清波。','é é é qū xiàng xiàng tiān gē|||bái máo fú lǜ shuǐ hóng zhǎng bō qīng bō','曲项：弯着脖子。歌：长鸣。拨：划动。\n','鹅鹅鹅，面向蓝天伸长脖子歌唱。白色羽毛浮在碧绿水面上，红色脚掌拨动清清的水波。',NULL,NULL,NULL,17,'2026-05-17 09:33:23','2026-05-17 09:33:23'),(23,'CP024','风','李峤','五言绝句','一年级',NULL,'李峤以风为题，从四季变化中捕捉风的力量——吹落叶、催花开、掀巨浪、斜万竿。\n----------\n【注解】\n解落：吹落。三秋：秋季。二月：春季。过：经过。斜：倾斜。\n\n----------\n【译文】\n风能吹落秋天的树叶，能吹开春天的花朵。吹过江面掀起巨浪，吹进竹林使万竿倾斜。','解落三秋叶，能开二月花。\n过江千尺浪，入竹万竿斜。','jiě luò sān qiū yè néng kāi èr yuè huā|||guò jiāng qiān chǐ làng rù zhú wàn gān xié','解落：吹落。三秋：秋季。二月：春季。过：经过。斜：倾斜。\n','风能吹落秋天的树叶，能吹开春天的花朵。吹过江面掀起巨浪，吹进竹林使万竿倾斜。',NULL,NULL,NULL,21,'2026-05-18 20:50:42','2026-05-18 20:50:42'),(24,'CP025','静夜思','李白','五言绝句','一年级','cloud://cloudbase-d6g5mlt4tbaa32ec2.636c-cloudbase-d6g5mlt4tbaa32ec2-1432544091/poem_images/24.png','李白客居异乡秋夜望月，以月光如霜起兴，举头低头间道尽游子思乡之情。\n----------\n【注解】\n静夜思：在静静的夜里产生的思绪。疑：好像。举头：抬头。\n\n----------\n【译文】\n明亮的月光洒在床前，好像地上泛起白霜。抬头望着天上明月，低头思念远方故乡。','床前明月光，疑是地上霜。\n举头望明月，低头思故乡。','chuáng qián míng yuè guāng yí shì dì shàng shuāng|||jǔ tóu wàng míng yuè dī tóu sī gù xiāng','静夜思：在静静的夜里产生的思绪。疑：好像。举头：抬头。\n','明亮的月光洒在床前，好像地上泛起白霜。抬头望着天上明月，低头思念远方故乡。',NULL,NULL,NULL,35,'2026-05-17 09:33:42','2026-05-17 09:33:42'),(25,'CP026','登鹳雀楼','王之涣','五言绝句','一年级',NULL,'王之涣登临鹳雀楼远眺，以白日依山、黄河入海写尽壮阔，更以更上层楼寄寓进取精神。\n----------\n【注解】\n鹳雀楼：旧址在山西永济。白日：太阳。依：依傍。尽：消失。欲：想要。穷：尽。更：再。\n\n----------\n【译文】\n夕阳依着山峦慢慢沉落，黄河朝着大海奔流。想看千里之外的风光，就要再登上一层高楼。','白日依山尽，黄河入海流。\n欲穷千里目，更上一层楼。','bái rì yī shān jǐn huáng hé rù hǎi liú|||yù qióng qiān lǐ mù gèng shàng yī céng lóu','鹳雀楼：旧址在山西永济。白日：太阳。依：依傍。尽：消失。欲：想要。穷：尽。更：再。\n','夕阳依着山峦慢慢沉落，黄河朝着大海奔流。想看千里之外的风光，就要再登上一层高楼。',NULL,NULL,NULL,23,'2026-05-17 20:25:39','2026-05-17 20:25:39'),(26,'CP027','春晓','孟浩然','五言绝句','一年级',NULL,'孟浩然隐居鹿门山时所作，春眠初醒闻啼鸟，忆夜来风雨，惜花落之情自然流露。\n----------\n【注解】\n晓：天亮。不觉晓：不知不觉天亮了。闻：听见。知多少：不知有多少。\n\n----------\n【译文】\n春天贪睡不知不觉天已亮，到处听见鸟的啼叫声。回想昨夜阵阵风雨，不知吹落了多少春花。','春眠不觉晓，处处闻啼鸟。\n夜来风雨声，花落知多少。','chūn mián bù jué xiǎo chù chù wén tí niǎo|||yè lái fēng yǔ shēng huā luò zhī duō shǎo','晓：天亮。不觉晓：不知不觉天亮了。闻：听见。知多少：不知有多少。\n','春天贪睡不知不觉天已亮，到处听见鸟的啼叫声。回想昨夜阵阵风雨，不知吹落了多少春花。',NULL,NULL,NULL,16,'2026-05-17 20:31:12','2026-05-17 20:31:12'),(27,'CP028','画','王维','五言绝句','一年级',NULL,'王维诗中有画的代表作，远山有色近水无声，以绘画之美写诗境之妙。\n----------\n【注解】\n色：颜色，也有景色之意。惊：吃惊，害怕。\n\n----------\n【译文】\n远看高山色彩明亮，走近却听不到水声。春天过去花依然在，人走近了鸟儿也不惊飞。','远看山有色，近听水无声。\n春去花还在，人来鸟不惊。','yuǎn kàn shān yǒu sè jìn tīng shuǐ wú shēng|||chūn qù huā hái zài rén lái niǎo bù jīng','色：颜色，也有景色之意。惊：吃惊，害怕。\n','远看高山色彩明亮，走近却听不到水声。春天过去花依然在，人走近了鸟儿也不惊飞。',NULL,NULL,NULL,9,NULL,'2026-05-15 13:38:34'),(28,'CP029','悯农（其一）','李绅','五言古诗','一年级',NULL,'李绅悯农诗之一，以锄禾日当午的辛劳与盘中餐的珍贵对比，呼号珍惜粮食。\n----------\n【注解】\n禾：谷类植物的统称。餐：饭食。\n\n----------\n【译文】\n烈日当空农民还在劳作，汗水滴入泥土。谁知道碗中米饭，每一粒都是辛苦得来的。','锄禾日当午，汗滴禾下土。\n谁知盘中餐，粒粒皆辛苦。','chú hé rì dāng wǔ hàn dī hé xià tǔ|||shuí zhī pán zhōng cān lì lì jiē xīn kǔ','禾：谷类植物的统称。餐：饭食。\n','烈日当空农民还在劳作，汗水滴入泥土。谁知道碗中米饭，每一粒都是辛苦得来的。',NULL,NULL,NULL,9,NULL,'2026-05-13 08:49:13'),(29,'CP030','悯农（其二）','李绅','五言古诗','一年级',NULL,'李绅悯农诗之二，春种秋收四海无闲田，农夫犹饿死的现实令人深思。\n----------\n【注解】\n粟：谷类。子：粮食颗粒。四海：全国。犹：仍然。\n\n----------\n【译文】\n春天种下一粒种子，秋天收获万颗粮食。天下没有荒废的田地，却仍有农民被饿死。','春种一粒粟，秋收万颗子。\n四海无闲田，农夫犹饿死。','chūn zhǒng yī lì sù qiū shōu wàn kē zi|||sì hǎi wú xián tián nóng fū yóu è sǐ','粟：谷类。子：粮食颗粒。四海：全国。犹：仍然。\n','春天种下一粒种子，秋天收获万颗粮食。天下没有荒废的田地，却仍有农民被饿死。',NULL,NULL,NULL,6,NULL,'2026-05-14 15:51:37'),(30,'CP031','寻隐者不遇','贾岛','五言古诗','一年级',NULL,'贾岛访友不遇，松下问童子的对答间，云深不知处道出隐者超然世外的意境。\n----------\n【注解】\n寻：寻访。隐者：隐士。不遇：没有见到。童子：小孩，指弟子。言：说。云深：云雾深处。\n\n----------\n【译文】\n松树下询问童子，他说师傅采药去了。就在这座山中，云雾缭绕不知在何处。','松下问童子，言师采药去。\n只在此山中，云深不知处。','sōng xià wèn tóng zi yán shī cǎi yào qù|||zhǐ zài cǐ shān zhōng yún shēn bù zhī chù','寻：寻访。隐者：隐士。不遇：没有见到。童子：小孩，指弟子。言：说。云深：云雾深处。\n','松树下询问童子，他说师傅采药去了。就在这座山中，云雾缭绕不知在何处。',NULL,NULL,NULL,3,NULL,'2026-05-12 21:02:43'),(31,'CP032','池上','白居易','五言绝句','一年级',NULL,'白居易以童趣入诗，小娃偷采白莲不解藏踪迹，浮萍一道开的画面天真烂漫。\n----------\n【注解】\n小娃：小孩。艇：小船。白莲：白色莲花。踪迹：痕迹。浮萍：水生植物。\n\n----------\n【译文】\n小孩撑着小船，偷偷采了白莲回来。不知道怎么掩藏踪迹，浮萍被船划开留下水路。','小娃撑小艇，偷采白莲回。\n不解藏踪迹，浮萍一道开。','xiǎo wá chēng xiǎo tǐng tōu cǎi bái lián huí|||bù jiě cáng zōng jì fú píng yī dào kāi','小娃：小孩。艇：小船。白莲：白色莲花。踪迹：痕迹。浮萍：水生植物。\n','小孩撑着小船，偷偷采了白莲回来。不知道怎么掩藏踪迹，浮萍被船划开留下水路。',NULL,NULL,NULL,7,NULL,'2026-05-12 21:48:11'),(32,'CP033','夜宿山寺','李白','五言绝句','一年级','cloud://cloudbase-d6g5mlt4tbaa32ec2.636c-cloudbase-d6g5mlt4tbaa32ec2-1432544091/poem_images/32.png','李白夜宿山寺，以危楼高百尺手可摘星辰的夸张，写尽山寺之高与敬畏之情。\n----------\n【注解】\n危楼：高楼。百尺：形容很高。星辰：天上的星星。语：说话。恐：害怕。惊：惊动。\n\n----------\n【译文】\n山上寺庙有百丈高，站在上面仿佛能摘下星星。不敢大声说话，怕惊动天上的仙人。','危楼高百尺，手可摘星辰。\n不敢高声语，恐惊天上人。','wēi lóu gāo bǎi chǐ shǒu kě zhāi xīng chén|||bù gǎn gāo shēng yǔ kǒng jīng tiān shàng rén','危楼：高楼。百尺：形容很高。星辰：天上的星星。语：说话。恐：害怕。惊：惊动。\n','山上寺庙有百丈高，站在上面仿佛能摘下星星。不敢大声说话，怕惊动天上的仙人。',NULL,NULL,NULL,9,'2026-05-17 09:32:27','2026-05-17 09:32:27'),(33,'CP034','绝句','杜甫','五言绝句','一年级',NULL,'杜甫居成都草堂时所作，迟日江山丽春风花草香，以细腻笔触写尽春光。\n----------\n【注解】\n迟日：春日。泥融：泥土湿润。鸳鸯：一种水鸟。\n\n----------\n【译文】\n春天的江山格外秀丽，春风吹来花草芳香。泥土融化燕子飞来筑巢，温暖的沙上睡着鸳鸯。','迟日江山丽，春风花草香。\n泥融飞燕子，沙暖睡鸳鸯。','chí rì jiāng shān lì chūn fēng huā cǎo xiāng|||ní róng fēi yàn zi shā nuǎn shuì yuān yāng','迟日：春日。泥融：泥土湿润。鸳鸯：一种水鸟。\n','春天的江山格外秀丽，春风吹来花草芳香。泥土融化燕子飞来筑巢，温暖的沙上睡着鸳鸯。',NULL,NULL,NULL,3,NULL,'2026-05-12 18:37:27'),(34,'CP035','江上渔者','范仲淹','五言绝句','一年级',NULL,'范仲淹以江上往来人与一叶扁舟对比，道出渔者出没风波里的艰辛。\n----------\n【注解】\n但：只。爱：喜欢。鲈鱼：一种味美的鱼。君：你。一叶舟：像树叶似的小船。出没：时隐时现。\n\n----------\n【译文】\n江上来来往往的人只喜爱鲈鱼的美味。你看那一叶小舟，在风浪里时隐时现。','江上往来人，但爱鲈鱼美。\n君看一叶舟，出没风波里。','jiāng shàng wǎng lái rén dàn ài lú yú měi|||jūn kàn yī yè zhōu chū méi fēng bō lǐ','但：只。爱：喜欢。鲈鱼：一种味美的鱼。君：你。一叶舟：像树叶似的小船。出没：时隐时现。\n','江上来来往往的人只喜爱鲈鱼的美味。你看那一叶小舟，在风浪里时隐时现。',NULL,NULL,NULL,10,NULL,'2026-05-13 11:43:42'),(35,'CP036','夏日绝句','李清照','五言绝句','一年级',NULL,'李清照借项羽不肯过江东的悲壮，抒发对英雄气概的敬仰与家国情怀。\n----------\n【注解】\n人杰：人中豪杰。鬼雄：鬼中英雄。项羽：秦末起义军领袖。江东：长江以东。\n\n----------\n【译文】\n活着当人中的俊杰，死了也要做鬼中的英雄。至今人们还在思念项羽，因为他不肯过江东偷生。','生当作人杰，死亦为鬼雄。\n至今思项羽，不肯过江东。','shēng dāng zuò rén jié sǐ yì wèi guǐ xióng|||zhì jīn sī xiàng yǔ bù kěn guò jiāng dōng','人杰：人中豪杰。鬼雄：鬼中英雄。项羽：秦末起义军领袖。江东：长江以东。\n','活着当人中的俊杰，死了也要做鬼中的英雄。至今人们还在思念项羽，因为他不肯过江东偷生。',NULL,NULL,NULL,7,NULL,'2026-05-13 11:57:49'),(36,'CP037','独坐敬亭山','李白','五言绝句','一年级','cloud://cloudbase-d6g5mlt4tbaa32ec2.636c-cloudbase-d6g5mlt4tbaa32ec2-1432544091/poem_images/36.png','李白独坐敬亭山，众鸟飞尽孤云独去，唯有青山相伴不厌，写尽孤独中的慰藉。\n----------\n【注解】\n敬亭山：在安徽宣城。尽：没有了。闲：悠闲。厌：满足。\n\n----------\n【译文】\n群鸟高飞远去，孤云独自悠闲。互相看着不厌倦，只有敬亭山理解我。','众鸟高飞尽，孤云独去闲。\n相看两不厌，只有敬亭山。','zhòng niǎo gāo fēi jǐn gū yún dú qù xián|||xiāng kàn liǎng bù yàn zhǐ yǒu jìng tíng shān','敬亭山：在安徽宣城。尽：没有了。闲：悠闲。厌：满足。\n','群鸟高飞远去，孤云独自悠闲。互相看着不厌倦，只有敬亭山理解我。',NULL,NULL,NULL,3,'2026-05-16 13:01:47','2026-05-16 13:01:45'),(37,'CP038','竹里馆','王维','五言绝句','一年级',NULL,'王维隐居辋川竹里馆，独坐幽篁弹琴长啸，深林明月相照间物我两忘。\n----------\n【注解】\n幽篁：幽深的竹林。啸：嘬口发出长而清脆的声音。\n\n----------\n【译文】\n独自坐在幽静竹林里，一边弹琴一边长啸。深林里无人知晓，只有明月来相伴。','独坐幽篁里，弹琴复长啸。\n深林人不知，明月来相照。','dú zuò yōu huáng lǐ dàn qín fù zhǎng xiào|||shēn lín rén bù zhī míng yuè lái xiāng zhào','幽篁：幽深的竹林。啸：嘬口发出长而清脆的声音。\n','独自坐在幽静竹林里，一边弹琴一边长啸。深林里无人知晓，只有明月来相伴。',NULL,NULL,NULL,7,'2026-05-16 16:13:39','2026-05-16 16:13:39'),(38,'CP039','鹿柴','王维','五言绝句','一年级','cloud://cloudbase-d6g5mlt4tbaa32ec2.636c-cloudbase-d6g5mlt4tbaa32ec2-1432544091/poem_images/38.png','王维辋川绝句，空山不见人但闻人语响，返景入深林复照青苔上，禅意悠远。\n----------\n【注解】\n鹿柴：辋川别业胜景。柴：通寨，栅栏。但：只。返景：落日反射的光。复：又。\n\n----------\n【译文】\n空山中看不见人，只听到人说话的声音。落日的余晖照入深林，又映在青苔上。','空山不见人，但闻人语响。\n返景入深林，复照青苔上。','kōng shān bù jiàn rén dàn wén rén yǔ xiǎng|||fǎn jǐng rù shēn lín fù zhào qīng tái shàng','鹿柴：辋川别业胜景。柴：通寨，栅栏。但：只。返景：落日反射的光。复：又。\n','空山中看不见人，只听到人说话的声音。落日的余晖照入深林，又映在青苔上。',NULL,NULL,NULL,3,'2026-05-16 16:13:53','2026-05-16 16:13:52'),(39,'CP040','乐游原','李商隐','五言绝句','一年级',NULL,'李商隐傍晚登乐游原，夕阳无限好只是近黄昏，以景写情道出人生迟暮之慨。\n----------\n【注解】\n乐游原：在长安城南。向晚：傍晚。不适：不快。古原：指乐游原。近：快要。\n\n----------\n【译文】\n傍晚心情不太好，驱车登上乐游原。夕阳无限美好，只是已近黄昏。','向晚意不适，驱车登古原。\n夕阳无限好，只是近黄昏。','xiàng wǎn yì bù shì qū chē dēng gǔ yuán|||xī yáng wú xiàn hǎo zhǐ shì jìn huáng hūn','乐游原：在长安城南。向晚：傍晚。不适：不快。古原：指乐游原。近：快要。\n','傍晚心情不太好，驱车登上乐游原。夕阳无限美好，只是已近黄昏。',NULL,NULL,NULL,5,'2026-05-18 21:06:12','2026-05-18 21:06:12'),(40,'CP041','村居','高鼎','七言绝句','二年级',NULL,'高鼎以草长莺飞二月天写春日村居之乐，儿童散学放纸鸢的画面充满生机。\n----------\n【注解】\n拂堤：拂过堤岸。醉：陶醉。春烟：春天的水汽。纸鸢：风筝。\n\n----------\n【译文】\n二月天草长莺飞，杨柳拂堤沉醉春烟。儿童早早放学回来，趁着东风放风筝。','草长莺飞二月天，拂堤杨柳醉春烟。\n儿童散学归来早，忙趁东风放纸鸢。','cǎo zhǎng yīng fēi èr yuè tiān fú dī yáng liǔ zuì chūn yān|||ér tóng sàn xué guī lái zǎo máng chèn dōng fēng fàng zhǐ yuān','拂堤：拂过堤岸。醉：陶醉。春烟：春天的水汽。纸鸢：风筝。\n','二月天草长莺飞，杨柳拂堤沉醉春烟。儿童早早放学回来，趁着东风放风筝。',NULL,NULL,NULL,2,NULL,'2026-05-12 18:37:31'),(41,'CP042','咏柳','贺知章','七言绝句','二年级',NULL,'贺知章以碧玉妆成万条垂下写柳，二月春风似剪刀的妙喻令人拍案。\n----------\n【注解】\n碧玉：比喻柳叶。妆：打扮。绦：丝带。裁：裁剪。似：好像。\n\n----------\n【译文】\n高高的柳树像碧玉妆成，万条垂下像绿色丝带。不知这细叶谁裁出来的，二月春风像剪刀。','碧玉妆成一树高，万条垂下绿丝绦。\n不知细叶谁裁出，二月春风似剪刀。','bì yù zhuāng chéng yī shù gāo wàn tiáo chuí xià lǜ sī tāo|||bù zhī xì yè shuí cái chū èr yuè chūn fēng shì jiǎn dāo','碧玉：比喻柳叶。妆：打扮。绦：丝带。裁：裁剪。似：好像。\n','高高的柳树像碧玉妆成，万条垂下像绿色丝带。不知这细叶谁裁出来的，二月春风像剪刀。',NULL,NULL,NULL,4,'2026-05-16 17:05:58','2026-05-16 17:05:58'),(42,'CP043','赋得古原草送别','白居易','五言律诗','二年级',NULL,'白居易以古原草的一岁一枯荣起兴，野火烧不尽春风吹又生传颂千古。\n----------\n【注解】\n离离：茂盛的样子。荣：茂盛。\n\n----------\n【译文】\n原野上茂盛的野草，一年一次枯萎又繁荣。野火烧不尽，春风吹又生。','离离原上草，一岁一枯荣。\n野火烧不尽，春风吹又生。','lí lí yuán shàng cǎo yī suì yī kū róng|||yě huǒ shāo bù jǐn chūn fēng chuī yòu shēng','离离：茂盛的样子。荣：茂盛。\n','原野上茂盛的野草，一年一次枯萎又繁荣。野火烧不尽，春风吹又生。',NULL,NULL,NULL,3,NULL,'2026-05-15 12:51:11'),(43,'CP044','赠汪伦','李白','七言绝句','二年级',NULL,'李白将行汪伦踏歌相送，桃花潭水深千尺不及汪伦送我情的比喻情深意切。\n----------\n【注解】\n汪伦：李白的朋友。踏歌：边走边唱。桃花潭：在安徽泾县。\n\n----------\n【译文】\n李白乘舟正要出发，忽然听到岸上传来踏歌声。桃花潭水深千尺，也比不上汪伦送我的情谊。','李白乘舟将欲行，忽闻岸上踏歌声。\n桃花潭水深千尺，不及汪伦送我情。','lǐ bái chéng zhōu jiāng yù xíng hū wén àn shàng tà gē shēng|||táo huā tán shuǐ shēn qiān chǐ bù jí wāng lún sòng wǒ qíng','汪伦：李白的朋友。踏歌：边走边唱。桃花潭：在安徽泾县。\n','李白乘舟正要出发，忽然听到岸上传来踏歌声。桃花潭水深千尺，也比不上汪伦送我的情谊。',NULL,NULL,NULL,2,'2026-05-16 17:08:24','2026-05-16 17:08:24'),(44,'CP045','望庐山瀑布','李白','七言绝句','二年级',NULL,'李白遥望庐山瀑布，飞流直下三千尺疑是银河落九天，气势磅礴想象奇绝。\n----------\n【注解】\n香炉：庐山香炉峰。紫烟：日光照射的紫色云雾。遥看：远远看去。银河：天河。\n\n----------\n【译文】\n日照香炉峰升起紫烟，远远望去瀑布挂在山前。飞流直下三千尺，让人怀疑是银河从天上落下来。','日照香炉生紫烟，遥看瀑布挂前川。\n飞流直下三千尺，疑是银河落九天。','rì zhào xiāng lú shēng zǐ yān yáo kàn pù bù guà qián chuān|||fēi liú zhí xià sān qiān chǐ yí shì yín hé luò jiǔ tiān','香炉：庐山香炉峰。紫烟：日光照射的紫色云雾。遥看：远远看去。银河：天河。\n','日照香炉峰升起紫烟，远远望去瀑布挂在山前。飞流直下三千尺，让人怀疑是银河从天上落下来。',NULL,NULL,NULL,4,NULL,'2026-05-13 09:32:00'),(45,'CP046','绝句','杜甫','七言绝句','二年级',NULL,'杜甫成都草堂之作，两个黄鹂一行白鹭，窗前千秋雪门泊万里船，时空交错。\n----------\n【注解】\n西岭：西岭雪山。千秋雪：千年不化的积雪。泊：停泊。东吴：古吴国。\n\n----------\n【译文】\n两只黄鹂在翠柳间鸣叫，一行白鹭飞上青天。窗外是西岭千年积雪，门前停着东吴的万里航船。','两个黄鹂鸣翠柳，一行白鹭上青天。\n窗含西岭千秋雪，门泊东吴万里船。','liǎng gè huáng lí míng cuì liǔ yī xíng bái lù shàng qīng tiān|||chuāng hán xī lǐng qiān qiū xuě mén pō dōng wú wàn lǐ chuán','西岭：西岭雪山。千秋雪：千年不化的积雪。泊：停泊。东吴：古吴国。\n','两只黄鹂在翠柳间鸣叫，一行白鹭飞上青天。窗外是西岭千年积雪，门前停着东吴的万里航船。',NULL,NULL,NULL,2,NULL,'2026-05-12 17:58:16'),(46,'CP047','所见','袁枚','五言绝句','二年级',NULL,'袁枚以牧童骑黄牛歌声振林樾写乡间所见，忽然闭口立的瞬间捕捉传神。\n----------\n【注解】\n牧童：放牛的孩子。振：回荡。林樾：树荫。欲：想要。捕：捉。\n\n----------\n【译文】\n牧童骑在黄牛背上，歌声在树林里回荡。忽然想捕捉鸣叫的知了，立刻停止唱歌站立不动。','牧童骑黄牛，歌声振林樾。\n意欲捕鸣蝉，忽然闭口立。','mù tóng qí huáng niú gē shēng zhèn lín yuè|||yì yù bǔ míng chán hū rán bì kǒu lì','牧童：放牛的孩子。振：回荡。林樾：树荫。欲：想要。捕：捉。\n','牧童骑在黄牛背上，歌声在树林里回荡。忽然想捕捉鸣叫的知了，立刻停止唱歌站立不动。',NULL,NULL,NULL,1,NULL,'2026-05-12 17:26:41'),(47,'CP048','晓出净慈寺送林子方','杨万里','七言绝句','二年级',NULL,'杨万里送友之作，接天莲叶无穷碧映日荷花别样红，写尽六月西湖之美。\n----------\n【注解】\n毕竟：到底。四时：四季。接天：与天相接。无穷碧：一望无际的绿色。\n\n----------\n【译文】\n到底是六月的西湖，风光与其他季节不同。接天的莲叶无穷碧绿，映日的荷花格外红艳。','毕竟西湖六月中，风光不与四时同。\n接天莲叶无穷碧，映日荷花别样红。','bì jìng xī hú liù yuè zhōng fēng guāng bù yǔ sì shí tóng|||jiē tiān lián yè wú qióng bì yìng rì hé huā bié yàng hóng','毕竟：到底。四时：四季。接天：与天相接。无穷碧：一望无际的绿色。\n','到底是六月的西湖，风光与其他季节不同。接天的莲叶无穷碧绿，映日的荷花格外红艳。',NULL,NULL,NULL,2,NULL,'2026-05-12 21:41:56'),(48,'CP049','回乡偶书','贺知章','七言绝句','二年级',NULL,'贺知章告老还乡时所作，少小离家老大回，儿童笑问客从何处来令人唏嘘。\n----------\n【注解】\n偶书：偶然写的。老大：年纪大了。衰：疏落。\n\n----------\n【译文】\n少小离家到老了才回来，乡音没变两鬓已斑白。孩子们见了我都不认识，笑着问客人从哪里来。','少小离家老大回，乡音无改鬓毛衰。\n儿童相见不相识，笑问客从何处来。','shǎo xiǎo lí jiā lǎo dà huí xiāng yīn wú gǎi bìn máo shuāi|||ér tóng xiāng jiàn bù xiāng shí xiào wèn kè cóng hé chù lái','偶书：偶然写的。老大：年纪大了。衰：疏落。\n','少小离家到老了才回来，乡音没变两鬓已斑白。孩子们见了我都不认识，笑着问客人从哪里来。',NULL,NULL,NULL,1,NULL,'2026-05-12 17:44:36'),(49,'CP050','赠刘景文','苏轼','七言绝句','二年级',NULL,'苏轼赠友勉励之作，荷尽菊残后橙黄橘绿时，一年好景须记取。\n----------\n【注解】\n擎：举。雨盖：雨伞，指荷叶。傲霜：不畏霜。君：你。橙黄橘绿：秋末冬初。\n\n----------\n【译文】\n荷花已谢没有遮雨的叶子，菊花凋残还有傲霜的枝条。一年好景你要记住，正是橙黄橘绿的时候。','荷尽已无擎雨盖，菊残犹有傲霜枝。\n一年好景君须记，最是橙黄橘绿时。','hé jǐn yǐ wú qíng yǔ gài jú cán yóu yǒu ào shuāng zhī|||yī nián hǎo jǐng jūn xū jì zuì shì chéng huáng jú lǜ shí','擎：举。雨盖：雨伞，指荷叶。傲霜：不畏霜。君：你。橙黄橘绿：秋末冬初。\n','荷花已谢没有遮雨的叶子，菊花凋残还有傲霜的枝条。一年好景你要记住，正是橙黄橘绿的时候。',NULL,NULL,NULL,2,NULL,'2026-05-13 09:26:12'),(50,'CP051','山行','杜牧','七言绝句','二年级',NULL,'杜牧山行所见，远上寒山石径斜白云生处有人家，停车坐爱枫林晚霜叶红于二月花。\n----------\n【注解】\n寒山：深秋的山。石径：石头小路。白云生处：白云升起的地方。坐：因为。\n\n----------\n【译文】\n沿着石头小路上寒山，白云深处有人家。停下车来因为喜爱枫林晚景，经霜的枫叶比二月花还红。','远上寒山石径斜，白云生处有人家。\n停车坐爱枫林晚，霜叶红于二月花。','yuǎn shàng hán shān shí jìng xié bái yún shēng chù yǒu rén jiā|||tíng chē zuò ài fēng lín wǎn shuāng yè hóng yú èr yuè huā','寒山：深秋的山。石径：石头小路。白云生处：白云升起的地方。坐：因为。\n','沿着石头小路上寒山，白云深处有人家。停下车来因为喜爱枫林晚景，经霜的枫叶比二月花还红。',NULL,NULL,NULL,1,NULL,'2026-05-12 17:30:09'),(51,'CP052','梅花','王安石','五言绝句','二年级',NULL,'王安石以墙角数枝梅凌寒独自开写梅之品格，遥知不是雪为有暗香来。\n----------\n【注解】\n凌寒：冒着严寒。遥：远远地。为：因为。暗香：幽香。\n\n----------\n【译文】\n墙角有几枝梅花，冒着严寒独自开放。远远就知道那不是雪，因为有幽香飘来。','墙角数枝梅，凌寒独自开。\n遥知不是雪，为有暗香来。','qiáng jiǎo shù zhī méi líng hán dú zì kāi|||yáo zhī bù shì xuě wèi yǒu àn xiāng lái','凌寒：冒着严寒。遥：远远地。为：因为。暗香：幽香。\n','墙角有几枝梅花，冒着严寒独自开放。远远就知道那不是雪，因为有幽香飘来。',NULL,NULL,NULL,9,'2026-05-16 17:09:32','2026-05-16 17:09:32'),(52,'CP053','小儿垂钓','胡令能','七言绝句','二年级',NULL,'胡令能以蓬头稚子学垂纶写儿童垂钓的专注，路人借问遥招手的细节传神。\n----------\n【注解】\n蓬头：头发蓬乱。稚子：小孩子。垂纶：钓鱼。莓苔：青苔。\n\n----------\n【译文】\n头发蓬乱的小孩学钓鱼，侧坐在青苔草丛中。路人问路远远招手，怕惊到鱼不敢答应。','蓬头稚子学垂纶，侧坐莓苔草映身。\n路人借问遥招手，怕得鱼惊不应人。','péng tóu zhì zi xué chuí lún cè zuò méi tái cǎo yìng shēn|||lù rén jiè wèn yáo zhāo shǒu pà dé yú jīng bù yīng rén','蓬头：头发蓬乱。稚子：小孩子。垂纶：钓鱼。莓苔：青苔。\n','头发蓬乱的小孩学钓鱼，侧坐在青苔草丛中。路人问路远远招手，怕惊到鱼不敢答应。',NULL,NULL,NULL,NULL,NULL,NULL),(53,'CP054','登飞来峰','王安石','七言绝句','二年级',NULL,'王安石登飞来峰，不畏浮云遮望眼自缘身在最高层，道出高瞻远瞩的气魄。\n----------\n【注解】\n飞来峰：在杭州灵隐寺前。千寻：形容极高。闻说：听说。\n\n----------\n【译文】\n飞来山上千寻高塔，听说鸡鸣时可看到日出。不怕浮云遮住视线，因为站在最高层。','飞来山上千寻塔，闻说鸡鸣见日升。\n不畏浮云遮望眼，自缘身在最高层。','fēi lái shān shàng qiān xún tǎ wén shuō jī míng jiàn rì shēng|||bù wèi fú yún zhē wàng yǎn zì yuán shēn zài zuì gāo céng','飞来峰：在杭州灵隐寺前。千寻：形容极高。闻说：听说。\n','飞来山上千寻高塔，听说鸡鸣时可看到日出。不怕浮云遮住视线，因为站在最高层。',NULL,NULL,NULL,1,NULL,'2026-05-13 09:32:15'),(54,'CP055','游子吟','孟郊','五言古诗','二年级',NULL,'孟郊以慈母手中线游子身上衣写尽母爱，谁言寸草心报得三春晖千古传唱。\n----------\n【注解】\n游子：离家在外的人。吟：诗歌体裁。临：将要。意恐：担心。寸草：小草，比喻子女。三春晖：春天的阳光，比喻母爱。\n\n----------\n【译文】\n慈母手中的针线，为远行的孩子赶制新衣。临行密密缝，怕孩子迟迟不归。谁说小草的心意，能报答春天阳光的恩情。','慈母手中线，游子身上衣。\n临行密密缝，意恐迟迟归。\n谁言寸草心，报得三春晖。','cí mǔ shǒu zhōng xiàn yóu zi shēn shàng yī|||lín xíng mì mì fèng yì kǒng chí chí guī|||shuí yán cùn cǎo xīn bào dé sān chūn huī','游子：离家在外的人。吟：诗歌体裁。临：将要。意恐：担心。寸草：小草，比喻子女。三春晖：春天的阳光，比喻母爱。\n','慈母手中的针线，为远行的孩子赶制新衣。临行密密缝，怕孩子迟迟不归。谁说小草的心意，能报答春天阳光的恩情。',NULL,NULL,NULL,1,NULL,'2026-05-12 16:47:38'),(55,'CP056','元日','王安石','七言绝句','三年级',NULL,'王安石写新年气象，爆竹声中一岁除春风送暖入屠苏，万象更新喜气洋洋。\n----------\n【注解】\n元日：农历正月初一。爆竹：鞭炮。一岁除：一年过去。屠苏：屠苏酒。新桃：新桃符。\n\n----------\n【译文】\n鞭炮声中一年过去，春风送暖喝屠苏酒。千家万户迎来新年的朝阳，都把新桃符换下旧的。','爆竹声中一岁除，春风送暖入屠苏。\n千门万户曈曈日，总把新桃换旧符。','bào zhú shēng zhōng yī suì chú chūn fēng sòng nuǎn rù tú sū|||qiān mén wàn hù tóng tóng rì zǒng bǎ xīn táo huàn jiù fú','元日：农历正月初一。爆竹：鞭炮。一岁除：一年过去。屠苏：屠苏酒。新桃：新桃符。\n','鞭炮声中一年过去，春风送暖喝屠苏酒。千家万户迎来新年的朝阳，都把新桃符换下旧的。',NULL,NULL,NULL,1,NULL,'2026-05-12 17:26:51'),(56,'CP057','清明','杜牧','七言绝句','三年级',NULL,'杜牧清明时节雨纷纷，路上行人欲断魂，借问酒家牧童遥指的问答情景交融。\n----------\n【注解】\n纷纷：形容雨多。欲断魂：形容伤感极深。借问：请问。遥指：远远地指。\n\n----------\n【译文】\n清明时节雨纷纷，路上行人满怀哀愁。请问哪里有酒家？牧童远远指向杏花村。','清明时节雨纷纷，路上行人欲断魂。\n借问酒家何处有？牧童遥指杏花村。','qīng míng shí jié yǔ fēn fēn lù shàng xíng rén yù duàn hún|||jiè wèn jiǔ jiā hé chù yǒu mù tóng yáo zhǐ xìng huā cūn','纷纷：形容雨多。欲断魂：形容伤感极深。借问：请问。遥指：远远地指。\n','清明时节雨纷纷，路上行人满怀哀愁。请问哪里有酒家？牧童远远指向杏花村。',NULL,NULL,NULL,NULL,NULL,NULL),(57,'CP058','九月九日忆山东兄弟','王维','七言绝句','三年级',NULL,'王维重阳思乡之作，独在异乡为异客每逢佳节倍思亲，引发千古共鸣。\n----------\n【注解】\n九月九日：重阳节。忆：想念。山东：华山以东。异客：他乡客。茱萸：一种香草。\n\n----------\n【译文】\n独自在他乡做客，每逢佳节更加思念亲人。遥想兄弟们登高时，都插着茱萸只少我一人。','独在异乡为异客，每逢佳节倍思亲。\n遥知兄弟登高处，遍插茱萸少一人。','dú zài yì xiāng wèi yì kè měi féng jiā jié bèi sī qīn|||yáo zhī xiōng dì dēng gāo chù biàn chā zhū yú shǎo yī rén','九月九日：重阳节。忆：想念。山东：华山以东。异客：他乡客。茱萸：一种香草。\n','独自在他乡做客，每逢佳节更加思念亲人。遥想兄弟们登高时，都插着茱萸只少我一人。',NULL,NULL,NULL,4,NULL,'2026-05-12 18:01:47'),(58,'CP059','望天门山','李白','七言绝句','三年级',NULL,'李白舟行望天门山，中断楚江开碧水东流回，两岸青山孤帆日边的壮丽画卷。\n----------\n【注解】\n天门山：在安徽当涂。中断：从中间断开。楚江：长江。回：回旋。\n\n----------\n【译文】\n天门山被楚江从中间冲开，碧水东流到这里又回旋。两岸青山相对而立，一片孤帆从日边驶来。','天门中断楚江开，碧水东流至此回。\n两岸青山相对出，孤帆一片日边来。','tiān mén zhōng duàn chǔ jiāng kāi bì shuǐ dōng liú zhì cǐ huí|||liǎng àn qīng shān xiāng duì chū gū fān yī piàn rì biān lái','天门山：在安徽当涂。中断：从中间断开。楚江：长江。回：回旋。\n','天门山被楚江从中间冲开，碧水东流到这里又回旋。两岸青山相对而立，一片孤帆从日边驶来。',NULL,NULL,NULL,NULL,NULL,NULL),(59,'CP060','饮湖上初晴后雨','苏轼','七言绝句','三年级',NULL,'苏轼以水光潋滟山色空蒙写西湖，淡妆浓抹总相宜的妙喻令人心折。\n----------\n【注解】\n潋滟：波光闪动。方好：正好。空蒙：烟雨迷茫。亦奇：也很奇妙。西子：西施。\n\n----------\n【译文】\n晴天波光粼粼正好看，雨天山色迷蒙也很奇妙。想把西湖比作西施，淡妆浓妆都很相宜。','水光潋滟晴方好，山色空蒙雨亦奇。\n欲把西湖比西子，淡妆浓抹总相宜。','shuǐ guāng liàn yàn qíng fāng hǎo shān sè kōng méng yǔ yì qí|||yù bǎ xī hú bǐ xī zi dàn zhuāng nóng mǒ zǒng xiāng yí','潋滟：波光闪动。方好：正好。空蒙：烟雨迷茫。亦奇：也很奇妙。西子：西施。\n','晴天波光粼粼正好看，雨天山色迷蒙也很奇妙。想把西湖比作西施，淡妆浓妆都很相宜。',NULL,NULL,NULL,NULL,NULL,NULL),(60,'CP061','望洞庭','刘禹锡','七言绝句','三年级',NULL,'刘禹锡秋夜望洞庭，湖光秋月潭面无风，白银盘里一青螺的比喻精巧绝伦。\n----------\n【注解】\n洞庭：洞庭湖。相和：互相映衬。镜未磨：未经打磨的铜镜。青螺：青色的田螺。\n\n----------\n【译文】\n湖光秋月两相映衬，湖面平静如未磨的镜面。远望洞庭山水青翠，像白银盘里托着青螺。','湖光秋月两相和，潭面无风镜未磨。\n遥望洞庭山水翠，白银盘里一青螺。','hú guāng qiū yuè liǎng xiāng hé tán miàn wú fēng jìng wèi mó|||yáo wàng dòng tíng shān shuǐ cuì bái yín pán lǐ yī qīng luó','洞庭：洞庭湖。相和：互相映衬。镜未磨：未经打磨的铜镜。青螺：青色的田螺。\n','湖光秋月两相映衬，湖面平静如未磨的镜面。远望洞庭山水青翠，像白银盘里托着青螺。',NULL,NULL,NULL,2,NULL,'2026-05-12 17:55:39'),(61,'CP062','早发白帝城','李白','七言绝句','三年级',NULL,'李白流放遇赦东归之作，朝辞白帝暮至江陵，轻舟已过万重山的畅快淋漓。\n----------\n【注解】\n白帝城：在今重庆奉节。朝辞：早晨辞别。彩云间：白帝城地势高。江陵：今湖北荆州。\n\n----------\n【译文】\n早晨辞别彩云间的白帝城，千里之外的江陵一天就到。两岸猿声啼不住，轻舟已过万重山。','朝辞白帝彩云间，千里江陵一日还。\n两岸猿声啼不住，轻舟已过万重山。','cháo cí bái dì cǎi yún jiān qiān lǐ jiāng líng yī rì hái|||liǎng àn yuán shēng tí bù zhù qīng zhōu yǐ guò wàn zhòng shān','白帝城：在今重庆奉节。朝辞：早晨辞别。彩云间：白帝城地势高。江陵：今湖北荆州。\n','早晨辞别彩云间的白帝城，千里之外的江陵一天就到。两岸猿声啼不住，轻舟已过万重山。',NULL,NULL,NULL,3,'2026-05-16 17:18:05','2026-05-16 17:18:05'),(62,'CP063','江雪','柳宗元','五言绝句','三年级',NULL,'柳宗元被贬永州时所作，千山鸟飞绝万径人踪灭，孤舟独钓寒江雪的遗世独立。\n----------\n【注解】\n绝：无。万径：千万条路。人踪：人的脚印。蓑笠：蓑衣斗笠。独：独自。\n\n----------\n【译文】\n所有山上飞鸟绝迹，所有道路不见人踪。孤舟上披蓑戴笠的老翁，独自在大雪中垂钓。','千山鸟飞绝，万径人踪灭。\n孤舟蓑笠翁，独钓寒江雪。','qiān shān niǎo fēi jué wàn jìng rén zōng miè|||gū zhōu suō lì wēng dú diào hán jiāng xuě','绝：无。万径：千万条路。人踪：人的脚印。蓑笠：蓑衣斗笠。独：独自。\n','所有山上飞鸟绝迹，所有道路不见人踪。孤舟上披蓑戴笠的老翁，独自在大雪中垂钓。',NULL,NULL,NULL,2,NULL,'2026-05-13 09:24:50'),(63,'CP064','忆江南','白居易','词','三年级',NULL,'白居易晚年回忆江南，日出江花红胜火春来江水绿如蓝，能不忆江南的深情缱绻。\n----------\n【注解】\n谙：熟悉。江花：江边的花。蓝：蓝草，可制染料。\n\n----------\n【译文】\n江南好，风景我曾熟悉。日出时江花红过火焰，春天江水绿如蓝草。怎能不怀念江南？','江南好，风景旧曾谙。\n日出江花红胜火，春来江水绿如蓝。\n能不忆江南？','jiāng nán hǎo fēng jǐng jiù céng ān|||rì chū jiāng huā hóng shèng huǒ chūn lái jiāng shuǐ lǜ rú lán|||néng bù yì jiāng nán','谙：熟悉。江花：江边的花。蓝：蓝草，可制染料。\n','江南好，风景我曾熟悉。日出时江花红过火焰，春天江水绿如蓝草。怎能不怀念江南？',NULL,NULL,NULL,3,'2026-05-18 21:07:41','2026-05-18 21:07:41'),(64,'CP065','滁州西涧','韦应物','七言绝句','三年级',NULL,'韦应物任滁州刺史时所作，独怜幽草涧边生，野渡无人舟自横的闲淡自然。\n----------\n【注解】\n独怜：偏爱。幽草：幽深处的草。深树：树林深处。野渡：野外渡口。\n\n----------\n【译文】\n偏爱涧边幽草，上面有黄鹂在深树中鸣叫。春潮带雨傍晚来得很急，荒野渡口无人小船独自漂。','独怜幽草涧边生，上有黄鹂深树鸣。\n春潮带雨晚来急，野渡无人舟自横。','dú lián yōu cǎo jiàn biān shēng shàng yǒu huáng lí shēn shù míng|||chūn cháo dài yǔ wǎn lái jí yě dù wú rén zhōu zì héng','独怜：偏爱。幽草：幽深处的草。深树：树林深处。野渡：野外渡口。\n','偏爱涧边幽草，上面有黄鹂在深树中鸣叫。春潮带雨傍晚来得很急，荒野渡口无人小船独自漂。',NULL,NULL,NULL,NULL,NULL,NULL),(65,'CP066','三衢道中','曾几','七言绝句','三年级',NULL,'曾几山行之作，梅子黄时日日晴小溪泛尽却山行，绿阴不减添得黄鹂的欣然。\n----------\n【注解】\n三衢：衢州。泛尽：坐船到尽头。却：再。不减：不减少。\n\n----------\n【译文】\n梅子黄时天天晴，坐船到尽头再走山路。绿荫不比来时少，还添了几声黄鹂叫。','梅子黄时日日晴，小溪泛尽却山行。\n绿阴不减来时路，添得黄鹂四五声。','méi zi huáng shí rì rì qíng xiǎo xī fàn jǐn què shān xíng|||lǜ yīn bù jiǎn lái shí lù tiān dé huáng lí sì wǔ shēng','三衢：衢州。泛尽：坐船到尽头。却：再。不减：不减少。\n','梅子黄时天天晴，坐船到尽头再走山路。绿荫不比来时少，还添了几声黄鹂叫。',NULL,NULL,NULL,NULL,NULL,NULL),(66,'CP067','惠崇春江晚景','苏轼','七言绝句','三年级',NULL,'苏轼为惠崇画题诗，竹外桃花春江水暖鸭先知，蒌蒿满地河豚欲上的春意盎然。\n----------\n【注解】\n惠崇：宋代画家。蒌蒿：一种水草。芦芽：芦苇嫩芽。河豚：一种鱼。\n\n----------\n【译文】\n竹林外桃花开了三两枝，春江水暖鸭子最先知道。蒌蒿满地芦芽短，正是河豚要上游的时候。','竹外桃花三两枝，春江水暖鸭先知。\n蒌蒿满地芦芽短，正是河豚欲上时。','zhú wài táo huā sān liǎng zhī chūn jiāng shuǐ nuǎn yā xiān zhī|||lóu hāo mǎn dì lú yá duǎn zhèng shì hé tún yù shàng shí','惠崇：宋代画家。蒌蒿：一种水草。芦芽：芦苇嫩芽。河豚：一种鱼。\n','竹林外桃花开了三两枝，春江水暖鸭子最先知道。蒌蒿满地芦芽短，正是河豚要上游的时候。',NULL,NULL,NULL,NULL,NULL,NULL),(67,'CP068','大林寺桃花','白居易','七言绝句','三年级',NULL,'白居易游庐山大林寺，人间四月芳菲尽山寺桃花始盛开，春归无觅处转入此中来。\n----------\n【注解】\n大林寺：在庐山。芳菲：花草的芳香。始：才。长恨：常常遗憾。\n\n----------\n【译文】\n人间四月百花凋零，山寺的桃花才刚盛开。常常遗憾春天归去无处找，不知它转入这里来。','人间四月芳菲尽，山寺桃花始盛开。\n长恨春归无觅处，不知转入此中来。','rén jiān sì yuè fāng fēi jǐn shān sì táo huā shǐ shèng kāi|||zhǎng hèn chūn guī wú mì chù bù zhī zhuǎn rù cǐ zhōng lái','大林寺：在庐山。芳菲：花草的芳香。始：才。长恨：常常遗憾。\n','人间四月百花凋零，山寺的桃花才刚盛开。常常遗憾春天归去无处找，不知它转入这里来。',NULL,NULL,NULL,3,NULL,'2026-05-12 21:42:16'),(68,'CP069','采莲曲','王昌龄','七言绝句','三年级',NULL,'王昌龄以荷叶罗裙一色裁写采莲女，乱入池中看不见闻歌始觉有人来的空灵。\n----------\n【注解】\n罗裙：丝罗裙子。一色裁：和荷叶同色。向脸：对着脸。\n\n----------\n【译文】\n荷叶和罗裙同一色，芙蓉对着脸两边开。混入池中看不见，听到歌声才知道有人来。','荷叶罗裙一色裁，芙蓉向脸两边开。\n乱入池中看不见，闻歌始觉有人来。','hé yè luó qún yī sè cái fú róng xiàng liǎn liǎng biān kāi|||luàn rù chí zhōng kàn bù jiàn wén gē shǐ jué yǒu rén lái','罗裙：丝罗裙子。一色裁：和荷叶同色。向脸：对着脸。\n','荷叶和罗裙同一色，芙蓉对着脸两边开。混入池中看不见，听到歌声才知道有人来。',NULL,NULL,NULL,1,NULL,'2026-05-12 18:01:59'),(69,'CP070','蝉','虞世南','五言绝句','三年级',NULL,'虞世南以蝉自喻，垂緌饮清露流响出疏桐，居高声自远非是藉秋风的品格自许。\n----------\n【注解】\n垂緌：垂下帽缨状的触须。清露：纯净的露水。流响：连续不断的鸣声。藉：凭借。\n\n----------\n【译文】\n蝉垂下触须饮清露，鸣声从稀疏的梧桐间传出。居高声音自然传得远，并非凭借秋风的力量。','垂緌饮清露，流响出疏桐。\n居高声自远，非是藉秋风。','chuí ruí yǐn qīng lù liú xiǎng chū shū tóng|||jū gāo shēng zì yuǎn fēi shì jí qiū fēng','垂緌：垂下帽缨状的触须。清露：纯净的露水。流响：连续不断的鸣声。藉：凭借。\n','蝉垂下触须饮清露，鸣声从稀疏的梧桐间传出。居高声音自然传得远，并非凭借秋风的力量。',NULL,NULL,NULL,NULL,NULL,NULL),(70,'CP071','出塞','王昌龄','七言绝句','四年级',NULL,'王昌龄出塞之作，秦时明月汉时关万里长征人未还，但使龙城飞将在的豪情。\n----------\n【注解】\n龙城飞将：指汉代名将李广。教：让。度：越过。阴山：在今内蒙古。\n\n----------\n【译文】\n明月还是秦汉时的明月，边关还是秦汉时的边关。万里长征的将士还未归来。只要龙城飞将在，绝不让胡人骑兵越过阴山。','秦时明月汉时关，万里长征人未还。\n但使龙城飞将在，不教胡马度阴山。','qín shí míng yuè hàn shí guān wàn lǐ zhǎng zhēng rén wèi hái|||dàn shǐ lóng chéng fēi jiāng zài bù jiào hú mǎ dù yīn shān','龙城飞将：指汉代名将李广。教：让。度：越过。阴山：在今内蒙古。\n','明月还是秦汉时的明月，边关还是秦汉时的边关。万里长征的将士还未归来。只要龙城飞将在，绝不让胡人骑兵越过阴山。',NULL,NULL,NULL,1,NULL,'2026-05-12 17:53:29'),(71,'CP072','凉州词','王翰','七言绝句','四年级',NULL,'王之涣凉州词，黄河远上白云间一片孤城万仞山，春风不度玉门关的苍凉。\n----------\n【注解】\n夜光杯：玉石做的酒杯。欲饮：正要喝。琵琶：乐器。催：催促出征。沙场：战场。\n\n----------\n【译文】\n葡萄美酒斟满夜光杯，正要喝酒琵琶马上催。醉倒在沙场请你别笑话，自古征战有几人能回？','葡萄美酒夜光杯，欲饮琵琶马上催。\n醉卧沙场君莫笑，古来征战几人回？','pú táo měi jiǔ yè guāng bēi yù yǐn pí pá mǎ shàng cuī|||zuì wò shā chǎng jūn mò xiào gǔ lái zhēng zhàn jǐ rén huí','夜光杯：玉石做的酒杯。欲饮：正要喝。琵琶：乐器。催：催促出征。沙场：战场。\n','葡萄美酒斟满夜光杯，正要喝酒琵琶马上催。醉倒在沙场请你别笑话，自古征战有几人能回？',NULL,NULL,NULL,NULL,NULL,NULL),(72,'CP073','题西林壁','苏轼','七言绝句','四年级',NULL,'苏轼游庐山题壁，横看成岭侧成峰远近高低各不同，不识庐山真面目的哲理。\n----------\n【注解】\n西林：庐山西林寺。横看：正面看。侧：侧面。各不同：各不相同。\n\n----------\n【译文】\n横看是岭侧看是峰，远近高低各不相同。看不清庐山真面目，只因为身在此山中。','横看成岭侧成峰，远近高低各不同。\n不识庐山真面目，只缘身在此山中。','héng kàn chéng lǐng cè chéng fēng yuǎn jìn gāo dī gè bù tóng|||bù shí lú shān zhēn miàn mù zhǐ yuán shēn zài cǐ shān zhōng','西林：庐山西林寺。横看：正面看。侧：侧面。各不同：各不相同。\n','横看是岭侧看是峰，远近高低各不相同。看不清庐山真面目，只因为身在此山中。',NULL,NULL,NULL,2,NULL,'2026-05-12 17:55:46'),(73,'CP074','游山西村','陆游','七言律诗','四年级',NULL,'陆游游山西村，山重水复疑无路柳暗花明又一村，道出绝处逢生的人生哲理。\n----------\n【注解】\n腊酒：腊月酿的酒。足鸡豚：丰盛的菜肴。山重水复：山重水绕。柳暗花明：柳色深绿花色明艳。\n\n----------\n【译文】\n不要笑话农家腊酒浑浊，丰收年留客菜肴丰盛。山重水复以为无路，柳暗花明又见一村。','莫笑农家腊酒浑，丰年留客足鸡豚。\n山重水复疑无路，柳暗花明又一村。','mò xiào nóng jiā là jiǔ hún fēng nián liú kè zú jī tún|||shān zhòng shuǐ fù yí wú lù liǔ àn huā míng yòu yī cūn','腊酒：腊月酿的酒。足鸡豚：丰盛的菜肴。山重水复：山重水绕。柳暗花明：柳色深绿花色明艳。\n','不要笑话农家腊酒浑浊，丰收年留客菜肴丰盛。山重水复以为无路，柳暗花明又见一村。',NULL,NULL,NULL,NULL,NULL,NULL),(74,'CP075','暮江吟','白居易','七言绝句','四年级',NULL,'白居易暮江之作，一道残阳铺水中半江瑟瑟半江红，可怜九月初三夜的精致。\n----------\n【注解】\n残阳：夕阳。铺：铺展。瑟瑟：碧绿色。可怜：可爱。真珠：珍珠。\n\n----------\n【译文】\n一道夕阳铺展在水中，半江碧绿半江红。最可爱九月初三的夜晚，露水像珍珠月亮像弯弓。','一道残阳铺水中，半江瑟瑟半江红。\n可怜九月初三夜，露似真珠月似弓。','yī dào cán yáng pù shuǐ zhōng bàn jiāng sè sè bàn jiāng hóng|||kě lián jiǔ yuè chū sān yè lù shì zhēn zhū yuè shì gōng','残阳：夕阳。铺：铺展。瑟瑟：碧绿色。可怜：可爱。真珠：珍珠。\n','一道夕阳铺展在水中，半江碧绿半江红。最可爱九月初三的夜晚，露水像珍珠月亮像弯弓。',NULL,NULL,NULL,NULL,NULL,NULL),(75,'CP076','雪梅','卢钺','七言绝句','四年级',NULL,'卢钺评梅雪之争，梅须逊雪三分白雪却输梅一段香，各有千秋的理性评判。\n----------\n【注解】\n降：服输。骚人：诗人。阁笔：放下笔。评章：评论。逊：不及。\n\n----------\n【译文】\n梅花和雪花争春互不服输，诗人放下笔费心评判。梅花须逊雪花三分白，雪花却输梅花一段香。','梅雪争春未肯降，骚人搁笔费评章。\n梅须逊雪三分白，雪却输梅一段香。','méi xuě zhēng chūn wèi kěn jiàng sāo rén gē bǐ fèi píng zhāng|||méi xū xùn xuě sān fēn bái xuě què shū méi yī duàn xiāng','降：服输。骚人：诗人。阁笔：放下笔。评章：评论。逊：不及。\n','梅花和雪花争春互不服输，诗人放下笔费心评判。梅花须逊雪花三分白，雪花却输梅花一段香。',NULL,NULL,NULL,NULL,NULL,NULL),(76,'CP077','芙蓉楼送辛渐','王昌龄','七言绝句','四年级',NULL,'王昌龄芙蓉楼送别，寒雨连江夜入吴，洛阳亲友如相问一片冰心在玉壶。\n----------\n【注解】\n芙蓉楼：在镇江。平明：天亮。冰心：纯洁的心。玉壶：玉制的壶。\n\n----------\n【译文】\n寒雨洒遍江天夜里入吴，清晨送客楚山显得孤独。洛阳亲友如果问起我，就说我的心如冰心在玉壶。','寒雨连江夜入吴，平明送客楚山孤。\n洛阳亲友如相问，一片冰心在玉壶。','hán yǔ lián jiāng yè rù wú píng míng sòng kè chǔ shān gū|||luò yáng qīn yǒu rú xiāng wèn yī piàn bīng xīn zài yù hú','芙蓉楼：在镇江。平明：天亮。冰心：纯洁的心。玉壶：玉制的壶。\n','寒雨洒遍江天夜里入吴，清晨送客楚山显得孤独。洛阳亲友如果问起我，就说我的心如冰心在玉壶。',NULL,NULL,NULL,2,NULL,'2026-05-15 13:41:31'),(77,'CP078','塞下曲','卢纶','五言绝句','四年级',NULL,'卢纶边塞之作，月黑雁飞高单于夜遁逃，欲将轻骑逐大雪满弓刀的紧张追杀。\n----------\n【注解】\n单于：匈奴首领。遁逃：逃跑。轻骑：轻装骑兵。逐：追赶。\n\n----------\n【译文】\n月黑夜大雁惊飞，单于趁夜逃跑。正要带轻骑兵追赶，大雪落满了弓箭和刀。','月黑雁飞高，单于夜遁逃。\n欲将轻骑逐，大雪满弓刀。','yuè hēi yàn fēi gāo dān yú yè dùn táo|||yù jiāng qīng qí zhú dà xuě mǎn gōng dāo','单于：匈奴首领。遁逃：逃跑。轻骑：轻装骑兵。逐：追赶。\n','月黑夜大雁惊飞，单于趁夜逃跑。正要带轻骑兵追赶，大雪落满了弓箭和刀。',NULL,NULL,NULL,NULL,NULL,NULL),(78,'CP079','墨梅','王冕','七言绝句','四年级',NULL,'王冕以墨梅自喻，不要人夸好颜色只留清气满乾坤，写尽淡泊名利的高洁品格。\n----------\n【注解】\n洗砚池：洗砚台的池子。淡墨痕：淡淡的墨色。清气：清香正气。乾坤：天地。\n\n----------\n【译文】\n我家洗砚池边的梅树，朵朵花开泛着淡墨痕。不需要别人夸颜色好，只愿清香正气充满天地间。','吾家洗砚池头树，朵朵花开淡墨痕。\n不要人夸好颜色，只留清气满乾坤。','wú jiā xǐ yàn chí tóu shù duǒ duǒ huā kāi dàn mò hén|||bù yào rén kuā hǎo yán sè zhǐ liú qīng qì mǎn qián kūn','洗砚池：洗砚台的池子。淡墨痕：淡淡的墨色。清气：清香正气。乾坤：天地。\n','我家洗砚池边的梅树，朵朵花开泛着淡墨痕。不需要别人夸颜色好，只愿清香正气充满天地间。',NULL,NULL,NULL,3,NULL,'2026-05-12 17:59:31'),(79,'CP080','蜂','罗隐','七言绝句','四年级',NULL,'罗隐以蜂喻人，采得百花成蜜后为谁辛苦为谁甜，道尽劳动者心酸与社会不公。\n----------\n【注解】\n不论：不管。山尖：山顶。尽被占：都被占领。\n\n----------\n【译文】\n不管平地还是山顶，无限风光都被蜜蜂占据。采得百花酿成蜜，为谁辛苦为谁甜？','不论平地与山尖，无限风光尽被占。\n采得百花成蜜后，为谁辛苦为谁甜？','bù lùn píng dì yǔ shān jiān wú xiàn fēng guāng jǐn bèi zhàn|||cǎi dé bǎi huā chéng mì hòu wèi shuí xīn kǔ wèi shuí tián','不论：不管。山尖：山顶。尽被占：都被占领。\n','不管平地还是山顶，无限风光都被蜜蜂占据。采得百花酿成蜜，为谁辛苦为谁甜？',NULL,NULL,NULL,1,NULL,'2026-05-12 17:55:52'),(80,'CP081','四时田园杂兴','范成大','七言绝句','四年级',NULL,'范成大写农家生活，昼出耘田夜绩麻村庄儿女各当家，童孙未解也傍桑阴学种瓜。\n----------\n【注解】\n耘田：除草。绩麻：把麻搓成线。未解：不懂。供：从事。傍：靠近。\n\n----------\n【译文】\n白天除草夜晚搓麻，村庄儿女各有所长。小孩子不懂耕织，也在桑树下学种瓜。','昼出耘田夜绩麻，村庄儿女各当家。\n童孙未解供耕织，也傍桑阴学种瓜。','zhòu chū yún tián yè jì má cūn zhuāng ér nǚ gè dāng jiā|||tóng sūn wèi jiě gōng gēng zhī yě bàng sāng yīn xué zhǒng guā','耘田：除草。绩麻：把麻搓成线。未解：不懂。供：从事。傍：靠近。\n','白天除草夜晚搓麻，村庄儿女各有所长。小孩子不懂耕织，也在桑树下学种瓜。',NULL,NULL,NULL,NULL,NULL,NULL),(81,'CP082','宿新市徐公店','杨万里','七言绝句','四年级',NULL,'杨万里宿新市徐公店，儿童急走追黄蝶飞入菜花无处寻，童趣盎然。\n----------\n【注解】\n篱落：篱笆。疏疏：稀疏。径：小路。新绿：新长的绿叶。急走：快跑。\n\n----------\n【译文】\n稀疏的篱笆旁小路深长，树上的新叶还没成荫。孩子快跑追黄蝶，飞入菜花无处寻。','篱落疏疏一径深，树头新绿未成阴。\n儿童急走追黄蝶，飞入菜花无处寻。','lí luò shū shū yī jìng shēn shù tóu xīn lǜ wèi chéng yīn|||ér tóng jí zǒu zhuī huáng dié fēi rù cài huā wú chù xún','篱落：篱笆。疏疏：稀疏。径：小路。新绿：新长的绿叶。急走：快跑。\n','稀疏的篱笆旁小路深长，树上的新叶还没成荫。孩子快跑追黄蝶，飞入菜花无处寻。',NULL,NULL,NULL,3,'2026-05-17 18:31:10','2026-05-17 18:31:10'),(82,'CP083','清平乐·村居','辛弃疾','词','四年级',NULL,'辛弃疾闲居带湖时所作，茅檐低小溪上青青草，白发翁媪醉里吴音的田园温情。\n----------\n【注解】\n清平乐：词牌名。茅檐：茅草屋檐。翁媪：老翁和老妇。亡赖：顽皮。\n\n----------\n【译文】\n茅草屋檐低矮，溪边长满青草。醉中听到吴地口音，不知是谁家的白发翁媪。大儿子在溪东锄豆，二儿子在织鸡笼。最喜欢小儿子顽皮，正躺在溪边剥莲蓬。','茅檐低小，溪上青青草。\n醉里吴音相媚好，白发谁家翁媪？\n大儿锄豆溪东，中儿正织鸡笼。\n最喜小儿亡赖，溪头卧剥莲蓬。','máo yán dī xiǎo xī shàng qīng qīng cǎo|||zuì lǐ wú yīn xiāng mèi hǎo bái fā shuí jiā wēng ǎo|||dà ér chú dòu xī dōng zhōng ér zhèng zhī jī lóng|||zuì xǐ xiǎo ér wáng lài xī tóu wò bō lián péng','清平乐：词牌名。茅檐：茅草屋檐。翁媪：老翁和老妇。亡赖：顽皮。\n','茅草屋檐低矮，溪边长满青草。醉中听到吴地口音，不知是谁家的白发翁媪。大儿子在溪东锄豆，二儿子在织鸡笼。最喜欢小儿子顽皮，正躺在溪边剥莲蓬。',NULL,NULL,NULL,2,'2026-05-16 17:20:53','2026-05-16 17:20:53'),(83,'CP084','卜算子·咏梅','毛泽东','词','四年级',NULL,'毛泽东以梅自喻，已是悬崖百丈冰犹有花枝俏，待到山花烂漫时她在丛中笑。\n----------\n【注解】\n卜算子：词牌名。归：回来。悬崖：高峻的峭壁。百丈冰：很厚的冰。俏：俊俏。烂漫：色彩绚丽。\n\n----------\n【译文】\n风风雨雨送走了春天，漫天飞雪又迎来春天。悬崖上已结了百丈冰，仍有花枝在俏丽绽放。俏也不争春光，只把春的消息来报。等到山花烂漫时，她在花丛中微笑。','风雨送春归，飞雪迎春到。\n已是悬崖百丈冰，犹有花枝俏。\n俏也不争春，只把春来报。\n待到山花烂漫时，她在丛中笑。','fēng yǔ sòng chūn guī fēi xuě yíng chūn dào|||yǐ shì xuán yá bǎi zhàng bīng yóu yǒu huā zhī qiào|||qiào yě bù zhēng chūn zhǐ bǎ chūn lái bào|||dài dào shān huā làn màn shí tā zài cóng zhōng xiào','卜算子：词牌名。归：回来。悬崖：高峻的峭壁。百丈冰：很厚的冰。俏：俊俏。烂漫：色彩绚丽。\n','风风雨雨送走了春天，漫天飞雪又迎来春天。悬崖上已结了百丈冰，仍有花枝在俏丽绽放。俏也不争春光，只把春的消息来报。等到山花烂漫时，她在花丛中微笑。',NULL,NULL,NULL,2,'2026-05-17 18:31:15','2026-05-17 18:31:15'),(84,'CP085','枫桥夜泊','张继','七言绝句','五年级',NULL,'张继夜泊枫桥，月落乌啼霜满天江枫渔火对愁眠，夜半钟声到客船的千古绝唱。\n----------\n【注解】\n枫桥：在苏州。泊：停船。乌啼：乌鸦啼叫。江枫：江边枫树。渔火：渔船上的灯火。姑苏：苏州。\n\n----------\n【译文】\n月亮落下乌鸦啼叫霜满天，面对江枫渔火满心愁绪。姑苏城外寒山寺，半夜钟声传到客船来。','月落乌啼霜满天，江枫渔火对愁眠。\n姑苏城外寒山寺，夜半钟声到客船。','yuè luò wū tí shuāng mǎn tiān jiāng fēng yú huǒ duì chóu mián|||gū sū chéng wài hán shān sì yè bàn zhōng shēng dào kè chuán','枫桥：在苏州。泊：停船。乌啼：乌鸦啼叫。江枫：江边枫树。渔火：渔船上的灯火。姑苏：苏州。\n','月亮落下乌鸦啼叫霜满天，面对江枫渔火满心愁绪。姑苏城外寒山寺，半夜钟声传到客船来。',NULL,NULL,NULL,NULL,NULL,NULL),(85,'CP086','长相思','纳兰性德','词','五年级',NULL,'纳兰性德随驾出关所作，山一程水一程夜深千帐灯，风一更雪一更故园无此声。\n----------\n【注解】\n长相思：词牌名。榆关：山海关。那畔：那边。聒：声音嘈杂。\n\n----------\n【译文】\n走过一山又一山，走过一水又一水。向着山海关那边走，深夜里千百顶帐篷亮着灯。刮了一更又一更风，下了一更又一更雪。吵碎了我思乡的心，故乡没有这种声音。','山一程，水一程，\n身向榆关那畔行，夜深千帐灯。\n风一更，雪一更，\n聒碎乡心梦不成，故园无此声。','shān yī chéng shuǐ yī chéng|||shēn xiàng yú guān nà pàn xíng yè shēn qiān zhàng dēng|||fēng yī gèng xuě yī gèng|||guā suì xiāng xīn mèng bù chéng gù yuán wú cǐ shēng','长相思：词牌名。榆关：山海关。那畔：那边。聒：声音嘈杂。\n','走过一山又一山，走过一水又一水。向着山海关那边走，深夜里千百顶帐篷亮着灯。刮了一更又一更风，下了一更又一更雪。吵碎了我思乡的心，故乡没有这种声音。',NULL,NULL,NULL,NULL,NULL,NULL),(86,'CP087','鸟鸣涧','王维','五言绝句','五年级',NULL,'王维以人闲桂花落夜静春山空写鸟鸣涧，月出惊山鸟时鸣春涧中的禅静。\n----------\n【注解】\n鸟鸣涧：鸟儿在山涧中鸣叫。闲：安静。春山：春日的山。时鸣：偶尔啼叫。\n\n----------\n【译文】\n人闲时桂花轻轻飘落，静静的夜里春山一片空寂。月亮升起惊动了山鸟，不时在春涧中啼叫。','人闲桂花落，夜静春山空。\n月出惊山鸟，时鸣春涧中。','rén xián guì huā luò yè jìng chūn shān kōng|||yuè chū jīng shān niǎo shí míng chūn jiàn zhōng','鸟鸣涧：鸟儿在山涧中鸣叫。闲：安静。春山：春日的山。时鸣：偶尔啼叫。\n','人闲时桂花轻轻飘落，静静的夜里春山一片空寂。月亮升起惊动了山鸟，不时在春涧中啼叫。',NULL,NULL,NULL,NULL,NULL,NULL),(87,'CP088','凉州词','王之涣','七言绝句','五年级',NULL,'王之涣凉州词，黄河远上白云间一片孤城万仞山，春风不度玉门关的苍凉。\n----------\n【注解】\n万仞：形容极高。羌笛：羌族乐器。何须：何必。杨柳：指折杨柳曲。玉门关：在今甘肃。\n\n----------\n【译文】\n黄河远远流向白云间，孤城坐落在万丈高山中。羌笛何必吹奏哀怨的杨柳曲，春风从来吹不到玉门关。','黄河远上白云间，一片孤城万仞山。\n羌笛何须怨杨柳，春风不度玉门关。','huáng hé yuǎn shàng bái yún jiān yī piàn gū chéng wàn rèn shān|||qiāng dí hé xū yuàn yáng liǔ chūn fēng bù dù yù mén guān','万仞：形容极高。羌笛：羌族乐器。何须：何必。杨柳：指折杨柳曲。玉门关：在今甘肃。\n','黄河远远流向白云间，孤城坐落在万丈高山中。羌笛何必吹奏哀怨的杨柳曲，春风从来吹不到玉门关。',NULL,NULL,NULL,NULL,NULL,NULL),(88,'CP089','黄鹤楼送孟浩然之广陵','李白','七言绝句','五年级',NULL,'李白黄鹤楼送孟浩然，孤帆远影碧空尽唯见长江天际流，以景写情的典范。\n----------\n【注解】\n广陵：扬州。故人：老朋友。烟花：指春天繁花似锦。碧空尽：消失在蓝天尽头。\n\n----------\n【译文】\n老朋友在西边的黄鹤楼告别，在繁花似锦的三月去扬州。孤帆远影消失在碧空尽头，只看见长江水在天边奔流。','故人西辞黄鹤楼，烟花三月下扬州。\n孤帆远影碧空尽，唯见长江天际流。','gù rén xī cí huáng hè lóu yān huā sān yuè xià yáng zhōu|||gū fān yuǎn yǐng bì kōng jǐn wéi jiàn zhǎng jiāng tiān jì liú','广陵：扬州。故人：老朋友。烟花：指春天繁花似锦。碧空尽：消失在蓝天尽头。\n','老朋友在西边的黄鹤楼告别，在繁花似锦的三月去扬州。孤帆远影消失在碧空尽头，只看见长江水在天边奔流。',NULL,NULL,NULL,1,NULL,'2026-05-12 17:56:19'),(89,'CP090','示儿','陆游','七言绝句','五年级',NULL,'陆游临终绝笔，死去元知万事空但悲不见九州同，王师北定中原日家祭无忘告乃翁。\n----------\n【注解】\n示儿：给儿子看。元知：本来知道。但悲：只悲伤。九州同：国家统一。王师：宋朝军队。乃翁：你的父亲。\n\n----------\n【译文】\n我本来知道死后万事皆空，只悲痛看不到国家统一。朝廷军队收复中原的那天，家祭时别忘了告诉你的父亲。','死去元知万事空，但悲不见九州同。\n王师北定中原日，家祭无忘告乃翁。','sǐ qù yuán zhī wàn shì kōng dàn bēi bù jiàn jiǔ zhōu tóng|||wáng shī běi dìng zhōng yuán rì jiā jì wú wàng gào nǎi wēng','示儿：给儿子看。元知：本来知道。但悲：只悲伤。九州同：国家统一。王师：宋朝军队。乃翁：你的父亲。\n','我本来知道死后万事皆空，只悲痛看不到国家统一。朝廷军队收复中原的那天，家祭时别忘了告诉你的父亲。',NULL,NULL,NULL,2,NULL,'2026-05-12 17:59:36'),(90,'CP091','题临安邸','林升','七言绝句','五年级',NULL,'林升题临安邸，山外青山楼外楼西湖歌舞几时休，暖风熏得游人醉直把杭州作汴州。\n----------\n【注解】\n邸：旅店。临安：杭州。直把：简直把。汴州：北宋都城开封。\n\n----------\n【译文】\n山外有青山楼外有楼，西湖歌舞什么时候才停休？暖风把游人吹得醉醺醺，简直把杭州当成了汴州。','山外青山楼外楼，西湖歌舞几时休？\n暖风熏得游人醉，直把杭州作汴州。','shān wài qīng shān lóu wài lóu xī hú gē wǔ jǐ shí xiū|||nuǎn fēng xūn dé yóu rén zuì zhí bǎ háng zhōu zuò biàn zhōu','邸：旅店。临安：杭州。直把：简直把。汴州：北宋都城开封。\n','山外有青山楼外有楼，西湖歌舞什么时候才停休？暖风把游人吹得醉醺醺，简直把杭州当成了汴州。',NULL,NULL,NULL,NULL,NULL,NULL),(91,'CP092','己亥杂诗','龚自珍','七言绝句','五年级',NULL,'龚自珍己亥年辞官南归时所作，我劝天公重抖擞不拘一格降人才的呐喊。\n----------\n【注解】\n九州：中国。恃：依靠。万马齐喑：比喻死气沉沉。抖擞：振作。不拘一格：打破常规。\n\n----------\n【译文】\n中国要有生气全靠风雷激荡，万马齐喑的局面实在可悲。我劝天公重新振作起来，不拘一格让人才降临人间。','九州生气恃风雷，万马齐喑究可哀。\n我劝天公重抖擞，不拘一格降人才。','jiǔ zhōu shēng qì shì fēng léi wàn mǎ qí yīn jiū kě āi|||wǒ quàn tiān gōng zhòng dǒu sǒu bù jū yī gé jiàng rén cái','九州：中国。恃：依靠。万马齐喑：比喻死气沉沉。抖擞：振作。不拘一格：打破常规。\n','中国要有生气全靠风雷激荡，万马齐喑的局面实在可悲。我劝天公重新振作起来，不拘一格让人才降临人间。',NULL,NULL,NULL,NULL,NULL,NULL),(92,'CP093','山居秋暝','王维','五言律诗','五年级',NULL,'王维隐居终南山时所作，明月松间照清泉石上流，竹喧归浣女莲动下渔舟的诗画合一。\n----------\n【注解】\n暝：傍晚。喧：喧笑。浣女：洗衣服的女子。随意：任凭。春芳：春天的花草。歇：消歇。王孙：指作者自己。\n\n----------\n【译文】\n空山刚下过雨，傍晚天气已是初秋。明月在松间映照，清泉在石上流淌。竹林喧哗知是浣女归来，莲叶晃动知是渔舟下水。任凭春天的花草凋谢，我自可留在山中。','空山新雨后，天气晚来秋。\n明月松间照，清泉石上流。\n竹喧归浣女，莲动下渔舟。\n随意春芳歇，王孙自可留。','kōng shān xīn yǔ hòu tiān qì wǎn lái qiū|||míng yuè sōng jiān zhào qīng quán shí shàng liú|||zhú xuān guī huàn nǚ lián dòng xià yú zhōu|||suí yì chūn fāng xiē wáng sūn zì kě liú','暝：傍晚。喧：喧笑。浣女：洗衣服的女子。随意：任凭。春芳：春天的花草。歇：消歇。王孙：指作者自己。\n','空山刚下过雨，傍晚天气已是初秋。明月在松间映照，清泉在石上流淌。竹林喧哗知是浣女归来，莲叶晃动知是渔舟下水。任凭春天的花草凋谢，我自可留在山中。',NULL,NULL,NULL,NULL,NULL,NULL),(93,'CP094','渔歌子','张志和','词','五年级',NULL,'张志和隐居江湖时所作，西塞山前白鹭飞桃花流水鳜鱼肥，斜风细雨不须归。\n----------\n【注解】\n渔歌子：词牌名。西塞山：在浙江湖州。鳜鱼：一种淡水鱼。箬笠：竹叶编的斗笠。蓑衣：草编的雨衣。\n\n----------\n【译文】\n西塞山前白鹭飞，桃花流水鳜鱼正肥。戴着青箬笠，披着绿蓑衣，斜风细雨不需要归去。','西塞山前白鹭飞，桃花流水鳜鱼肥。\n青箬笠，绿蓑衣，斜风细雨不须归。','xī sāi shān qián bái lù fēi táo huā liú shuǐ guì yú féi|||qīng ruò lì lǜ suō yī xié fēng xì yǔ bù xū guī','渔歌子：词牌名。西塞山：在浙江湖州。鳜鱼：一种淡水鱼。箬笠：竹叶编的斗笠。蓑衣：草编的雨衣。\n','西塞山前白鹭飞，桃花流水鳜鱼正肥。戴着青箬笠，披着绿蓑衣，斜风细雨不需要归去。',NULL,NULL,NULL,NULL,NULL,NULL),(94,'CP095','观书有感','朱熹','七言绝句','五年级',NULL,'朱熹以半亩方塘一鉴开喻读书，问渠那得清如许为有源头活水来的哲理。\n----------\n【注解】\n方塘：方形池塘。鉴：镜子。徘徊：来回移动。渠：它，指方塘。那得：怎么会。如许：如此。\n\n----------\n【译文】\n半亩方塘像一面打开的镜子，天光云影在水面来回移动。问那塘水怎么会如此清澈？因为有源头的活水不断流来。','半亩方塘一鉴开，天光云影共徘徊。\n问渠那得清如许？为有源头活水来。','bàn mǔ fāng táng yī jiàn kāi tiān guāng yún yǐng gòng pái huái|||wèn qú nà dé qīng rú xǔ wèi yǒu yuán tóu huó shuǐ lái','方塘：方形池塘。鉴：镜子。徘徊：来回移动。渠：它，指方塘。那得：怎么会。如许：如此。\n','半亩方塘像一面打开的镜子，天光云影在水面来回移动。问那塘水怎么会如此清澈？因为有源头的活水不断流来。',NULL,NULL,NULL,NULL,NULL,NULL),(95,'CP096','劝学','颜真卿','七言绝句','五年级',NULL,'颜真卿劝学诗，三更灯火五更鸡正是男儿读书时，黑发不知勤学早白首方悔读书迟。\n----------\n【注解】\n三更：夜里十一点到一点。五更鸡：天亮时。黑发：指少年。白首：指老年。\n\n----------\n【译文】\n三更灯火五更鸡叫时，正是男儿读书的好时光。年少时不知勤奋学习，到老了才后悔读书太少。','三更灯火五更鸡，正是男儿读书时。\n黑发不知勤学早，白首方悔读书迟。','sān gèng dēng huǒ wǔ gèng jī zhèng shì nán ér dú shū shí|||hēi fā bù zhī qín xué zǎo bái shǒu fāng huǐ dú shū chí','三更：夜里十一点到一点。五更鸡：天亮时。黑发：指少年。白首：指老年。\n','三更灯火五更鸡叫时，正是男儿读书的好时光。年少时不知勤奋学习，到老了才后悔读书太少。',NULL,NULL,NULL,NULL,NULL,NULL),(96,'CP097','牧童','吕岩','七言绝句','五年级',NULL,'吕岩以牧童生活写隐逸之趣，归来饱饭黄昏后不脱蓑衣卧月明的闲适自在。\n----------\n【注解】\n铺：铺展。弄：吹奏。三四声：形容笛声稀疏。卧月明：躺在月光下。\n\n----------\n【译文】\n青草铺满了六七里原野，晚风中传来三四声笛声。回家吃完饭已是黄昏后，连蓑衣也不脱就躺在月光下。','草铺横野六七里，笛弄晚风三四声。\n归来饱饭黄昏后，不脱蓑衣卧月明。','cǎo pù héng yě liù qī lǐ dí nòng wǎn fēng sān sì shēng|||guī lái bǎo fàn huáng hūn hòu bù tuō suō yī wò yuè míng','铺：铺展。弄：吹奏。三四声：形容笛声稀疏。卧月明：躺在月光下。\n','青草铺满了六七里原野，晚风中传来三四声笛声。回家吃完饭已是黄昏后，连蓑衣也不脱就躺在月光下。',NULL,NULL,NULL,4,NULL,'2026-05-15 13:41:44'),(97,'CP098','舟过安仁','杨万里','七言绝句','五年级',NULL,'杨万里舟过安仁见两小童，怪生无雨都张伞不是遮头是使风的童趣观察。\n----------\n【注解】\n安仁：地名。篙：撑船竿。棹：船桨。怪生：怪不得。使风：利用风力。\n\n----------\n【译文】\n一叶渔船上有两个小孩，收起篙和桨坐在船里。怪不得没下雨也撑开伞，不是为了遮雨而是当帆使。','一叶渔船两小童，收篙停棹坐船中。\n怪生无雨都张伞，不是遮头是使风。','yī yè yú chuán liǎng xiǎo tóng shōu gāo tíng zhào zuò chuán zhōng|||guài shēng wú yǔ dōu zhāng sǎn bù shì zhē tóu shì shǐ fēng','安仁：地名。篙：撑船竿。棹：船桨。怪生：怪不得。使风：利用风力。\n','一叶渔船上有两个小孩，收起篙和桨坐在船里。怪不得没下雨也撑开伞，不是为了遮雨而是当帆使。',NULL,NULL,NULL,1,NULL,'2026-05-12 17:45:13'),(98,'CP099','清平乐','黄庭坚','词','五年级',NULL,'黄庭坚以春归何处寂寞无行路写惜春，百啭无人能解因风飞过蔷薇的无奈。\n----------\n【注解】\n清平乐：词牌名。行路：道路。唤取：叫来。因风：借着风。\n\n----------\n【译文】\n春天去了哪里？寂寞得找不到它的踪迹。如果有人知道春天的去处，请叫它回来和我们同住。春天无影无踪谁知道？除非去问黄鹂。可黄鹂叫了千百遍也没人听懂，它已趁着风飞过蔷薇花丛。','春归何处？寂寞无行路。\n若有人知春去处，唤取归来同住。\n春无踪迹谁知？除非问取黄鹂。\n百啭无人能解，因风飞过蔷薇。','chūn guī hé chù jì mò wú xíng lù|||ruò yǒu rén zhī chūn qù chù huàn qǔ guī lái tóng zhù|||chūn wú zōng jì shuí zhī chú fēi wèn qǔ huáng lí|||bǎi zhuàn wú rén néng jiě yīn fēng fēi guò qiáng wēi','清平乐：词牌名。行路：道路。唤取：叫来。因风：借着风。\n','春天去了哪里？寂寞得找不到它的踪迹。如果有人知道春天的去处，请叫它回来和我们同住。春天无影无踪谁知道？除非去问黄鹂。可黄鹂叫了千百遍也没人听懂，它已趁着风飞过蔷薇花丛。',NULL,NULL,NULL,NULL,NULL,NULL),(99,'CP100','宿建德江','孟浩然','五言绝句','六年级',NULL,'孟浩然漫游吴越时宿建德江，野旷天低树江清月近人，日暮客愁新的孤寂。\n----------\n【注解】\n建德江：新安江的一段。移舟：移动小船。泊：停船。烟渚：烟雾笼罩的小洲。客：诗人自己。\n\n----------\n【译文】\n把小船停靠在烟雾迷蒙的小洲边，日暮时分新的愁绪又涌上心头。原野空旷天比树还低，江水清清月亮好像来亲近人。','移舟泊烟渚，日暮客愁新。\n野旷天低树，江清月近人。','yí zhōu pō yān zhǔ rì mù kè chóu xīn|||yě kuàng tiān dī shù jiāng qīng yuè jìn rén','建德江：新安江的一段。移舟：移动小船。泊：停船。烟渚：烟雾笼罩的小洲。客：诗人自己。\n','把小船停靠在烟雾迷蒙的小洲边，日暮时分新的愁绪又涌上心头。原野空旷天比树还低，江水清清月亮好像来亲近人。',NULL,NULL,NULL,3,NULL,'2026-05-16 10:00:29'),(100,'CP101','浪淘沙','刘禹锡','七言绝句','六年级',NULL,'刘禹锡以九曲黄河万里沙浪淘风簸自天涯写黄河，直上银河的浪漫想象。\n----------\n【注解】\n浪淘沙：曲调名。九曲：形容河道曲折。万里沙：黄河流经万里带来泥沙。簸：颠簸。\n\n----------\n【译文】\n九曲黄河挟带万里泥沙，风浪颠簸来自天涯。如今我要直上银河去，一同到牵牛织女家。','九曲黄河万里沙，浪淘风簸自天涯。\n如今直上银河去，同到牵牛织女家。','jiǔ qū huáng hé wàn lǐ shā làng táo fēng bǒ zì tiān yá|||rú jīn zhí shàng yín hé qù tóng dào qiān niú zhī nǚ jiā','浪淘沙：曲调名。九曲：形容河道曲折。万里沙：黄河流经万里带来泥沙。簸：颠簸。\n','九曲黄河挟带万里泥沙，风浪颠簸来自天涯。如今我要直上银河去，一同到牵牛织女家。',NULL,NULL,NULL,NULL,NULL,NULL),(101,'CP102','江南春','杜牧','七言绝句','六年级',NULL,'杜牧以千里莺啼绿映红写江南春色，南朝四百八十寺多少楼台烟雨中。\n----------\n【注解】\n山郭：山城。酒旗：酒馆的旗帜。南朝：东晋后的宋齐梁陈。四百八十寺：形容寺庙很多。\n\n----------\n【译文】\n千里江南黄莺啼叫绿映红花，水乡山城酒旗在风中飘扬。南朝留下四百八十座寺庙，多少楼台笼罩在烟雨之中。','千里莺啼绿映红，水村山郭酒旗风。\n南朝四百八十寺，多少楼台烟雨中。','qiān lǐ yīng tí lǜ yìng hóng shuǐ cūn shān guō jiǔ qí fēng|||nán cháo sì bǎi bā shí sì duō shǎo lóu tái yān yǔ zhōng','山郭：山城。酒旗：酒馆的旗帜。南朝：东晋后的宋齐梁陈。四百八十寺：形容寺庙很多。\n','千里江南黄莺啼叫绿映红花，水乡山城酒旗在风中飘扬。南朝留下四百八十座寺庙，多少楼台笼罩在烟雨之中。',NULL,NULL,NULL,1,NULL,'2026-05-12 21:42:27'),(102,'CP103','书湖阴先生壁','王安石','七言绝句','六年级',NULL,'王安石题壁之作，一水护田将绿绕两山排闼送青来，对仗精工意境优美。\n----------\n【注解】\n湖阴先生：王安石的朋友。畦：田垄。排闼：推开门。\n\n----------\n【译文】\n茅屋檐下常打扫干净无青苔，花木成行亲手栽种。一条溪水护着农田将绿色环绕，两座青山推开门送来青翠。','茅檐长扫净无苔，花木成畦手自栽。\n一水护田将绿绕，两山排闼送青来。','máo yán zhǎng sǎo jìng wú tái huā mù chéng qí shǒu zì zāi|||yī shuǐ hù tián jiāng lǜ rào liǎng shān pái tà sòng qīng lái','湖阴先生：王安石的朋友。畦：田垄。排闼：推开门。\n','茅屋檐下常打扫干净无青苔，花木成行亲手栽种。一条溪水护着农田将绿色环绕，两座青山推开门送来青翠。',NULL,NULL,NULL,NULL,NULL,NULL),(103,'CP104','马诗','李贺','五言绝句','六年级',NULL,'李贺以马自喻，大漠沙如雪燕山月似钩，何当金络脑快走踏清秋的建功渴望。\n----------\n【注解】\n大漠：广大的沙漠。燕山：山名。钩：弯月。何当：什么时候。金络脑：黄金笼头。快走：奔驰。\n\n----------\n【译文】\n大沙漠里沙如雪，燕山顶上月如钩。什么时候才能戴上黄金笼头，在秋高气爽的疆场上奔驰。','大漠沙如雪，燕山月似钩。\n何当金络脑，快走踏清秋。','dà mò shā rú xuě yàn shān yuè shì gōu|||hé dāng jīn luò nǎo kuài zǒu tà qīng qiū','大漠：广大的沙漠。燕山：山名。钩：弯月。何当：什么时候。金络脑：黄金笼头。快走：奔驰。\n','大沙漠里沙如雪，燕山顶上月如钩。什么时候才能戴上黄金笼头，在秋高气爽的疆场上奔驰。',NULL,NULL,NULL,NULL,NULL,NULL),(104,'CP105','石灰吟','于谦','七言绝句','六年级',NULL,'于谦少年时所作，粉骨碎身浑不怕要留清白在人间的铮铮誓言传颂千古。\n----------\n【注解】\n千锤万凿：无数次锤打开凿。若等闲：好像很平常。浑：全。清白：指石灰的白色，也指人品纯洁。\n\n----------\n【译文】\n千锤万凿从深山中取出来，烈火焚烧也看成平常事。粉身碎骨全不怕，要把清白的品格留在人间。','千锤万凿出深山，烈火焚烧若等闲。\n粉骨碎身浑不怕，要留清白在人间。','qiān chuí wàn záo chū shēn shān liè huǒ fén shāo ruò děng xián|||fěn gǔ suì shēn hún bù pà yào liú qīng bái zài rén jiān','千锤万凿：无数次锤打开凿。若等闲：好像很平常。浑：全。清白：指石灰的白色，也指人品纯洁。\n','千锤万凿从深山中取出来，烈火焚烧也看成平常事。粉身碎骨全不怕，要把清白的品格留在人间。',NULL,NULL,NULL,NULL,NULL,NULL),(105,'CP106','竹石','郑燮','七言绝句','六年级',NULL,'郑燮以竹自喻，千磨万击还坚劲任尔东西南北风，写尽坚韧不拔的品格。\n----------\n【注解】\n竹石：长在石缝中的竹子。咬定：牢牢扎根。立根：扎根。原：本来。任尔：任凭你。\n\n----------\n【译文】\n咬定青山不放松，根扎在破裂的岩石中。千磨万击仍然坚劲，任凭你东西南北的风。','咬定青山不放松，立根原在破岩中。\n千磨万击还坚劲，任尔东西南北风。','yǎo dìng qīng shān bù fàng sōng lì gēn yuán zài pò yán zhōng|||qiān mó wàn jī hái jiān jìn rèn ěr dōng xī nán běi fēng','竹石：长在石缝中的竹子。咬定：牢牢扎根。立根：扎根。原：本来。任尔：任凭你。\n','咬定青山不放松，根扎在破裂的岩石中。千磨万击仍然坚劲，任凭你东西南北的风。',NULL,NULL,NULL,NULL,NULL,NULL),(106,'CP107','寒食','韩翃','七言绝句','六年级',NULL,'韩翃以春城无处不飞花写寒食节，日暮汉宫传蜡烛轻烟散入五侯家的含蓄讽刺。\n----------\n【注解】\n寒食：清明节前两天，禁火吃冷食。御柳：宫中的柳树。传蜡烛：皇帝赐蜡烛给权贵。五侯：指权贵。\n\n----------\n【译文】\n春天的长安城到处飘飞花，寒食节东风吹动宫中柳。黄昏时皇宫在传赐蜡烛，轻烟飘进权贵家。','春城无处不飞花，寒食东风御柳斜。\n日暮汉宫传蜡烛，轻烟散入五侯家。','chūn chéng wú chù bù fēi huā hán shí dōng fēng yù liǔ xié|||rì mù hàn gōng chuán là zhú qīng yān sàn rù wǔ hóu jiā','寒食：清明节前两天，禁火吃冷食。御柳：宫中的柳树。传蜡烛：皇帝赐蜡烛给权贵。五侯：指权贵。\n','春天的长安城到处飘飞花，寒食节东风吹动宫中柳。黄昏时皇宫在传赐蜡烛，轻烟飘进权贵家。',NULL,NULL,NULL,NULL,NULL,NULL),(107,'CP108','十五夜望月','王建','七言绝句','六年级',NULL,'王建中秋望月，中庭地白树栖鸦冷露无声湿桂花，不知秋思落谁家的深沉思念。\n----------\n【注解】\n中庭：庭院中。地白：月光照地发白。栖：栖息。秋思：秋天的愁思。\n\n----------\n【译文】\n庭院地上月光白树上有鸦，冷露无声打湿桂花。今夜明月人人都在望，不知秋天的愁思会落在谁家。','中庭地白树栖鸦，冷露无声湿桂花。\n今夜月明人尽望，不知秋思落谁家。','zhōng tíng dì bái shù qī yā lěng lù wú shēng shī guì huā|||jīn yè yuè míng rén jǐn wàng bù zhī qiū sī luò shuí jiā','中庭：庭院中。地白：月光照地发白。栖：栖息。秋思：秋天的愁思。\n','庭院地上月光白树上有鸦，冷露无声打湿桂花。今夜明月人人都在望，不知秋天的愁思会落在谁家。',NULL,NULL,NULL,NULL,NULL,NULL),(108,'CP109','送元二使安西','王维','七言绝句','六年级',NULL,'王维渭城送别，劝君更尽一杯酒西出阳关无故人，以酒写情的千古送别名篇。\n----------\n【注解】\n渭城：咸阳。浥：湿润。阳关：在甘肃敦煌。\n\n----------\n【译文】\n渭城早晨的雨润湿了尘土，客舍旁的柳树显得格外青翠。请你再饮一杯送别酒，向西出了阳关就见不到老朋友了。','渭城朝雨浥轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。','wèi chéng cháo yǔ yì qīng chén kè shě qīng qīng liǔ sè xīn|||quàn jūn gèng jǐn yī bēi jiǔ xī chū yáng guān wú gù rén','渭城：咸阳。浥：湿润。阳关：在甘肃敦煌。\n','渭城早晨的雨润湿了尘土，客舍旁的柳树显得格外青翠。请你再饮一杯送别酒，向西出了阳关就见不到老朋友了。',NULL,NULL,NULL,NULL,NULL,NULL),(109,'CP110','春夜喜雨','杜甫','五言律诗','六年级',NULL,'杜甫居成都草堂时写春雨，随风潜入夜润物细无声，晓看红湿处花重锦官城。\n----------\n【注解】\n乃：就。发生：催发植物生长。潜：悄悄地。润物：滋润万物。野径：野外小路。花重：花沾雨水显得沉重。\n\n----------\n【译文】\n好雨知道时节，春天来了就下起来。随着风悄悄潜入夜里，滋润万物细密无声。野外小路乌云笼罩，江上船只灯火独明。天亮看那红湿的地方，花朵沉甸甸开满锦官城。','好雨知时节，当春乃发生。\n随风潜入夜，润物细无声。\n野径云俱黑，江船火独明。\n晓看红湿处，花重锦官城。','hǎo yǔ zhī shí jié dāng chūn nǎi fā shēng|||suí fēng qián rù yè rùn wù xì wú shēng|||yě jìng yún jù hēi jiāng chuán huǒ dú míng|||xiǎo kàn hóng shī chù huā zhòng jǐn guān chéng','乃：就。发生：催发植物生长。潜：悄悄地。润物：滋润万物。野径：野外小路。花重：花沾雨水显得沉重。\n','好雨知道时节，春天来了就下起来。随着风悄悄潜入夜里，滋润万物细密无声。野外小路乌云笼罩，江上船只灯火独明。天亮看那红湿的地方，花朵沉甸甸开满锦官城。',NULL,NULL,NULL,NULL,NULL,NULL),(110,'CP111','早春呈水部张十八员外','韩愈','七言绝句','六年级',NULL,'韩愈早春诗，天街小雨润如酥草色遥看近却无，最是一年春好处的细腻。\n----------\n【注解】\n天街：京城街道。酥：酥油。遥看：远看。绝胜：远远胜过。皇都：京城。\n\n----------\n【译文】\n京城街道小雨润如酥油，远看草色青青近看却无。这是一年中最美好的春景，远远胜过烟柳满皇都。','天街小雨润如酥，草色遥看近却无。\n最是一年春好处，绝胜烟柳满皇都。','tiān jiē xiǎo yǔ rùn rú sū cǎo sè yáo kàn jìn què wú|||zuì shì yī nián chūn hǎo chù jué shèng yān liǔ mǎn huáng dōu','天街：京城街道。酥：酥油。遥看：远看。绝胜：远远胜过。皇都：京城。\n','京城街道小雨润如酥油，远看草色青青近看却无。这是一年中最美好的春景，远远胜过烟柳满皇都。',NULL,NULL,NULL,NULL,NULL,NULL),(111,'CP112','泊船瓜洲','王安石','七言绝句','六年级',NULL,'王安石泊船瓜洲，春风又绿江南岸明月何时照我还，绿字为炼字典范。\n----------\n【注解】\n瓜洲：在今扬州。京口：镇江。间：隔开。钟山：南京紫金山。还：回来。\n\n----------\n【译文】\n京口和瓜洲只有一水之隔，钟山也只隔着几重山。春风又吹绿江南岸，明月什么时候照我回还？','京口瓜洲一水间，钟山只隔数重山。\n春风又绿江南岸，明月何时照我还。','jīng kǒu guā zhōu yī shuǐ jiān zhōng shān zhǐ gé shù zhòng shān|||chūn fēng yòu lǜ jiāng nán àn míng yuè hé shí zhào wǒ hái','瓜洲：在今扬州。京口：镇江。间：隔开。钟山：南京紫金山。还：回来。\n','京口和瓜洲只有一水之隔，钟山也只隔着几重山。春风又吹绿江南岸，明月什么时候照我回还？',NULL,NULL,NULL,NULL,NULL,NULL),(112,'CP113','游园不值','叶绍翁','七言绝句','六年级',NULL,'叶绍翁游园不值，春色满园关不住一枝红杏出墙来的哲理名句传颂千古。\n----------\n【注解】\n不值：没有遇到主人。应怜：大概是怜惜。屐齿：木屐底的齿。小扣：轻轻敲门。柴扉：柴门。\n\n----------\n【译文】\n大概是主人怜惜青苔怕被踩坏，轻轻敲门久久不开。满园春色关不住，一枝红杏探出墙来。','应怜屐齿印苍苔，小扣柴扉久不开。\n春色满园关不住，一枝红杏出墙来。','yīng lián jī chǐ yìn cāng tái xiǎo kòu chái fēi jiǔ bù kāi|||chūn sè mǎn yuán guān bù zhù yī zhī hóng xìng chū qiáng lái','不值：没有遇到主人。应怜：大概是怜惜。屐齿：木屐底的齿。小扣：轻轻敲门。柴扉：柴门。\n','大概是主人怜惜青苔怕被踩坏，轻轻敲门久久不开。满园春色关不住，一枝红杏探出墙来。',NULL,NULL,NULL,NULL,NULL,NULL),(113,'CP114','浣溪沙','苏轼','词','六年级',NULL,'苏轼游蕲水清泉寺时所作，谁道人生无再少门前流水尚能西的豁达乐观。\n----------\n【注解】\n浣溪沙：词牌名。兰芽：兰草的嫩芽。浸：泡在水中。子规：杜鹃鸟。无再少：青春不再。尚能西：还能向西流。\n\n----------\n【译文】\n山下兰草嫩芽浸在溪水里，松间沙路干净无泥。傍晚细雨中杜鹃声声啼。谁说人生不能再年轻？门前的溪水还能向西流！不要白发苍苍还唱着黄鸡催晓。','山下兰芽短浸溪，松间沙路净无泥，\n萧萧暮雨子规啼。\n谁道人生无再少？门前流水尚能西！\n休将白发唱黄鸡。','shān xià lán yá duǎn jìn xī sōng jiān shā lù jìng wú ní|||xiāo xiāo mù yǔ zi guī tí|||shuí dào rén shēng wú zài shǎo mén qián liú shuǐ shàng néng xī|||xiū jiāng bái fā chàng huáng jī','浣溪沙：词牌名。兰芽：兰草的嫩芽。浸：泡在水中。子规：杜鹃鸟。无再少：青春不再。尚能西：还能向西流。\n','山下兰草嫩芽浸在溪水里，松间沙路干净无泥。傍晚细雨中杜鹃声声啼。谁说人生不能再年轻？门前的溪水还能向西流！不要白发苍苍还唱着黄鸡催晓。',NULL,NULL,NULL,4,NULL,'2026-05-13 09:17:04'),(114,'CP115','卜算子·送鲍浩然之浙东','王观','词','六年级',NULL,'王观送鲍浩然，水是眼波横山是眉峰聚，若到江南赶上春千万和春住的俏皮。\n----------\n【注解】\n卜算子：词牌名。之：往。眼波：眼神。眉峰：眉毛。盈盈：美好的样子。\n\n----------\n【译文】\n水像美人流转的眼波，山像美人蹙起的眉峰。想问行人去哪里？眉眼盈盈的地方。刚刚送走春天，又要送你离去。如果到江南还能赶上春天，千万和春天一起留下。','水是眼波横，山是眉峰聚。\n欲问行人去那边？眉眼盈盈处。\n才始送春归，又送君归去。\n若到江南赶上春，千万和春住。','shuǐ shì yǎn bō héng shān shì méi fēng jù|||yù wèn xíng rén qù nà biān méi yǎn yíng yíng chù|||cái shǐ sòng chūn guī yòu sòng jūn guī qù|||ruò dào jiāng nán gǎn shàng chūn qiān wàn hé chūn zhù','卜算子：词牌名。之：往。眼波：眼神。眉峰：眉毛。盈盈：美好的样子。\n','水像美人流转的眼波，山像美人蹙起的眉峰。想问行人去哪里？眉眼盈盈的地方。刚刚送走春天，又要送你离去。如果到江南还能赶上春天，千万和春天一起留下。',NULL,NULL,NULL,3,NULL,'2026-05-16 11:52:57'),(115,'CP116','长歌行','汉乐府','乐府诗','六年级',NULL,'汉乐府民歌，以朝露待日晞起兴，少壮不努力老大徒伤悲的警世名言。\n----------\n【注解】\n长歌行：乐府曲调名。朝露：早晨的露水。晞：晒干。布：施予。德泽：恩惠。焜黄：枯黄。\n\n----------\n【译文】\n园中葵菜青翠欲滴，清晨的露水等待阳光晒干。春天布施恩泽，万物生机勃勃。常怕秋天到来，花叶枯黄凋零。百川东流入大海，什么时候再向西流回？年少时不努力，到老了只能白白悲伤。','青青园中葵，朝露待日晞。\n阳春布德泽，万物生光辉。\n常恐秋节至，焜黄华叶衰。\n百川东到海，何时复西归？\n少壮不努力，老大徒伤悲。','qīng qīng yuán zhōng kuí cháo lù dài rì xī|||yáng chūn bù dé zé wàn wù shēng guāng huī|||cháng kǒng qiū jié zhì kūn huáng huá yè shuāi|||bǎi chuān dōng dào hǎi hé shí fù xī guī|||shǎo zhuàng bù nǔ lì lǎo dà tú shāng bēi','长歌行：乐府曲调名。朝露：早晨的露水。晞：晒干。布：施予。德泽：恩惠。焜黄：枯黄。\n','园中葵菜青翠欲滴，清晨的露水等待阳光晒干。春天布施恩泽，万物生机勃勃。常怕秋天到来，花叶枯黄凋零。百川东流入大海，什么时候再向西流回？年少时不努力，到老了只能白白悲伤。',NULL,NULL,NULL,5,'2026-05-16 17:21:56','2026-05-16 17:21:56'),(116,'CP117','七步诗','曹植','五言古诗','六年级',NULL,'曹植七步成诗的本事诗，煮豆燃豆萁本自同根生相煎何太急的兄弟相残之痛。\n----------\n【注解】\n豆萁：豆秆。釜：锅。泣：小声哭。本：原本。煎：煎熬。何太急：为什么这么急迫。\n\n----------\n【译文】\n锅里煮着豆子，豆秆在锅下燃烧。豆子在锅里哭泣：我们本是同根所生，你为什么这么急迫地煎熬我？','煮豆燃豆萁，豆在釜中泣。\n本是同根生，相煎何太急？','zhǔ dòu rán dòu qí dòu zài fǔ zhōng qì|||běn shì tóng gēn shēng xiāng jiān hé tài jí','豆萁：豆秆。釜：锅。泣：小声哭。本：原本。煎：煎熬。何太急：为什么这么急迫。\n','锅里煮着豆子，豆秆在锅下燃烧。豆子在锅里哭泣：我们本是同根所生，你为什么这么急迫地煎熬我？',NULL,NULL,NULL,NULL,NULL,NULL),(117,'CP118','迢迢牵牛星','古诗十九首','五言古诗','六年级',NULL,'古诗十九首之一，以牵牛织女隔河汉写人间相思，盈盈一水间脉脉不得语。\n----------\n【注解】\n迢迢：遥远的样子。皎皎：明亮。纤纤：纤细。擢：举起。札札：织机声。机杼：织布机。脉脉：含情相望。\n\n----------\n【译文】\n遥远的牵牛星，明亮的织女星。织女举起纤纤素手，札札地摆弄织机。一整天织不成布匹，眼泪如雨般落下。银河又清又浅，相隔又有多少距离？只隔一水之间，含情脉脉不得交谈。','迢迢牵牛星，皎皎河汉女。\n纤纤擢素手，札札弄机杼。\n终日不成章，泣涕零如雨。\n河汉清且浅，相去复几许。\n盈盈一水间，脉脉不得语。','tiáo tiáo qiān niú xīng jiǎo jiǎo hé hàn nǚ|||xiān xiān zhuó sù shǒu zhá zhá nòng jī zhù|||zhōng rì bù chéng zhāng qì tì líng rú yǔ|||hé hàn qīng qiě qiǎn xiāng qù fù jǐ xǔ|||yíng yíng yī shuǐ jiān mài mài bù dé yǔ','迢迢：遥远的样子。皎皎：明亮。纤纤：纤细。擢：举起。札札：织机声。机杼：织布机。脉脉：含情相望。\n','遥远的牵牛星，明亮的织女星。织女举起纤纤素手，札札地摆弄织机。一整天织不成布匹，眼泪如雨般落下。银河又清又浅，相隔又有多少距离？只隔一水之间，含情脉脉不得交谈。',NULL,NULL,NULL,3,'2026-05-16 17:22:16','2026-05-16 17:22:16'),(118,'CP119','采薇（节选）','诗经','四言古诗','六年级',NULL,'《诗经·小雅》名篇，昔我往矣杨柳依依今我来思雨雪霏霏，以景写情的典范。\n----------\n【注解】\n采薇：采摘野豌豆。昔：从前。往：出征。依依：柳枝飘拂。思：语助词。雨雪：下雪。霏霏：雪花飞舞。\n\n----------\n【译文】\n从前我出征的时候，杨柳飘飘。如今我回来了，大雪纷飞。道路泥泞难行，又渴又饿。我心中万分悲伤，没有人知道我的哀愁。','昔我往矣，杨柳依依。\n今我来思，雨雪霏霏。\n行道迟迟，载渴载饥。\n我心伤悲，莫知我哀！','xī wǒ wǎng yǐ yáng liǔ yī yī|||jīn wǒ lái sī yǔ xuě fēi fēi|||xíng dào chí chí zài kě zài jī|||wǒ xīn shāng bēi mò zhī wǒ āi','采薇：采摘野豌豆。昔：从前。往：出征。依依：柳枝飘拂。思：语助词。雨雪：下雪。霏霏：雪花飞舞。\n','从前我出征的时候，杨柳飘飘。如今我回来了，大雪纷飞。道路泥泞难行，又渴又饿。我心中万分悲伤，没有人知道我的哀愁。',NULL,NULL,NULL,12,'2026-05-16 16:45:40','2026-05-16 16:45:40');
