INSERT INTO `followread_record` VALUES (1778557429382,'xiaoming','','',8,'绝句',10,'{\"overallScore\":10,\"overallComment\":\"你已经能准确背出《绝句》中的一句啦，这是很棒的开始！只要你下次专注于古诗内容，一句一句积累，慢慢就能完整流畅地背诵整首诗啦，加油！\",\"dimensions\":[{\"name\":\"准确性\",\"score\":10,\"weight\":40,\"comment\":\"仅正确背诵了“一行白鹭上青天”这一句，其余内容均为与古诗无关的话语，存在大量多读、错读的情况\",\"encourage\":\"你能准确背出其中一句已经很棒啦，下次可以专注在古诗内容上，慢慢把其他句子也记牢哦！\"},{\"name\":\"完整度\",\"score\":10,\"weight\":25,\"comment\":\"仅覆盖了原文四句中的一句，未背诵剩余三句内容，完整度不足\",\"encourage\":\"没关系，咱们可以一句一句来背，先把每一句都记熟，再连起来，慢慢就能背完整啦！\"},{\"name\":\"流利度\",\"score\":10,\"weight\":20,\"comment\":\"背诵过程中夹杂了大量与古诗无关的内容，背诵不连贯，流利度较差\",\"encourage\":\"下次背诵时可以先静下心来，专注于古诗本身，慢慢尝试连贯地背诵，你一定可以做到的！\"},{\"name\":\"发音建议\",\"score\":10,\"weight\":15,\"comment\":\"已背诵的“一行白鹭上青天”未发现明显发音问题，但其余古诗字词未涉及，无法全面评估\",\"encourage\":\"你正确背诵的这句发音很标准哦，继续保持，等你背其他句子时，也可以这样准确发音！\"}]}','','2026-05-12 11:43:49',NULL),(1778558112000,'xiaoming','','',5,'悯农（其二）',0,'{\"overallScore\":0,\"overallComment\":\"AI评分未就绪，请重试\",\"dimensions\":[]}','就是刚才发生了就是 我这边不是\n就刚才点的停止之后\n好了少了一句我点停止点完停止之后他自\n对要么刚才直接出 bug 了嗯','2026-05-12 11:55:11',NULL),(1778558395529,'xiaoming','','',10,'清明',10,'{\"overallScore\":10,\"overallComment\":\"这次背诵可能是因为紧张或者还没熟悉原文内容，没关系，只要多花时间熟悉诗句，逐字逐句练习，下次一定能有很大进步哦！\",\"dimensions\":[{\"name\":\"准确性\",\"score\":10,\"weight\":40,\"comment\":\"仅“借问酒家”四字与原文相符，其余均为无关表述，存在大量错读、漏读情况\",\"encourage\":\"没关系，这次可能是紧张啦，下次先熟悉原文内容，逐字核对背诵，一定会越来越准确的！\"},{\"name\":\"完整度\",\"score\":10,\"weight\":25,\"comment\":\"仅提及原文极少部分内容，未覆盖《清明》的主要诗句，完整度极低\",\"encourage\":\"别灰心，我们可以把诗句分成小段来记忆，逐步覆盖全部内容，你可以的！\"},{\"name\":\"流利度\",\"score\":10,\"weight\":20,\"comment\":\"背诵内容混乱，语句不连贯，无法形成完整的诗句表述\",\"encourage\":\"慢慢来，先把诗句读熟，再尝试连贯背诵，相信你能做到流畅背诵的！\"},{\"name\":\"发音建议\",\"score\":10,\"weight\":15,\"comment\":\"原文中的“牧童”读成了“木头”，“杏花村”读成了“这些话村”，发音偏差较大，且大部分为无关内容，难以判断原文字词发音\",\"encourage\":\"之后可以对着原文逐字练习发音，把每个字读准，慢慢积累，发音一定会越来越标准的！\"}]}','请不过这个录音确实很\n不是吗是啊 我感觉\n借问酒家\n现在一句话就能提交了啊木头要这些话村','2026-05-12 11:59:55',NULL),(1778558820285,'xiaoming','小明','',4,'登鹳雀楼',42,'{\"overallScore\":42,\"overallComment\":\"这次背诵虽然有一些错漏，但你读对的部分发音很清晰，只要多熟悉《登鹳雀楼》的诗句内容，下次肯定能背得更准确完整，继续加油哦！\",\"dimensions\":[{\"name\":\"准确性\",\"score\":30,\"weight\":40,\"comment\":\"仅“黄河入海流欲穷千里目”部分字词与原文一致，开头错读成无关内容“有两米三的”，结尾漏读“更上一层楼”且添加了无关语句，存在较多错读、漏读、多读情况\",\"encourage\":\"没关系，咱们先把整首诗的内容记熟，一点点来，你读对的部分发音很清楚哦！\"},{\"name\":\"完整度\",\"score\":50,\"weight\":25,\"comment\":\"仅覆盖了原文的两个分句，遗漏了开头“白日依山尽”和结尾“更上一层楼”两个核心分句，未完整覆盖原文主要内容\",\"encourage\":\"多跟着原文读几遍，慢慢就能把整首诗都背下来啦，你可以的！\"},{\"name\":\"流利度\",\"score\":40,\"weight\":20,\"comment\":\"背诵过程中出现错读无关内容的情况，整体连贯性较差，仅正确的分句部分相对流畅\",\"encourage\":\"只要对诗句足够熟悉，你肯定能背得越来越顺畅，加油！\"},{\"name\":\"发音建议\",\"score\":60,\"weight\":15,\"comment\":\"正确读出的字词发音清晰标准，未发现明显发音不准的问题，但需先准确掌握诗句内容，避免错读无关语句\",\"encourage\":\"你读对的部分发音很好听，继续保持这个发音状态，记牢诗句后会表现得更出色！\"}]}','有两米三的\n黄河入海流\n欲穷千里目\n对我感觉这个音色怎么这么','2026-05-12 12:07:00',NULL),(1778590681426,'xiaoming','','',27,'画',85,'{\"overallScore\":85,\"overallComment\":\"你整体背诵表现很不错，虽然有几处小失误，但流畅度和完整度都值得肯定，继续努力，下次一定能精准背诵出整首《画》！\",\"dimensions\":[{\"name\":\"准确性\",\"score\":88,\"weight\":40,\"comment\":\"背诵时将原文的“近听水无声”读成了“静听水无声”，“春去花还在”读成了“春秋花还在”，存在两处字词错误，其余字词均正确。\",\"encourage\":\"你已经记住了大部分内容，下次注意“近”和“去”这两个字的正确表述，就更棒啦！\"},{\"name\":\"完整度\",\"score\":80,\"weight\":25,\"comment\":\"背诵覆盖了原文的全部四句内容，仅存在两处字词替换，没有漏读或多读的情况，整体内容完整度较好。\",\"encourage\":\"你能完整背出整首诗的框架，继续保持，争取完全贴合原文内容哦！\"},{\"name\":\"流利度\",\"score\":85,\"weight\":20,\"comment\":\"背诵过程较为流畅，没有明显的卡顿、重复或停顿，节奏把握不错。\",\"encourage\":\"你的背诵节奏很稳，继续保持这个流畅的状态，会越来越熟练的！\"},{\"name\":\"发音建议\",\"score\":82,\"weight\":15,\"comment\":\"需要注意区分“近（jìn）”与“静（jìng）”、“去（qù）”与“秋（qiū）”的发音，避免因发音相近而混淆字词。\",\"encourage\":\"多加练习这几组易混字词的发音，你的发音会越来越标准准确的！\"}]}','远看山有色\n静听水无声\n春秋花还在\n人来鸟不惊','2026-05-12 20:58:01',NULL),(1778591823503,'xiaoming','','',7,'江雪',85,'{\"overallScore\":85,\"overallComment\":\"你在跟读过程中已经展现出不错的基础，大部分内容能流畅朗读，继续针对易错字词和语调节奏多加练习，你的跟读水平一定会有更大的提升！\",\"dimensions\":[{\"name\":\"发音准确度\",\"score\":88,\"weight\":40,\"comment\":\"部分字词发音准确，如“鸟飞绝”“独钓寒江雪”读音标准，但存在多处读音错误：“千”误读为“天”，“径”误读为“静”，“人踪灭”读成“陈宗业”，“孤舟蓑笠翁”读成“古咒说”，声母韵母的清晰度有待提升。\",\"encourage\":\"继续练习易错字词的发音，相信你能把每个字都读得越来越标准！\"},{\"name\":\"语调模仿\",\"score\":80,\"weight\":25,\"comment\":\"整体语调有一定起伏，能跟上原文的大致语气，但在错误读音的部分语调衔接不够自然，抑扬顿挫的模仿还可以更贴合标准语音。\",\"encourage\":\"多听标准朗读的语调变化，慢慢模仿，你的语调会越来越到位的！\"},{\"name\":\"流利度\",\"score\":85,\"weight\":20,\"comment\":\"朗读过程中没有明显磕巴，整体较为流畅，但遇到易错字词时略有停顿，影响了流畅度的一致性。\",\"encourage\":\"继续熟悉原文内容，减少停顿，你的朗读会越来越流畅自然哦！\"},{\"name\":\"节奏感\",\"score\":82,\"weight\":15,\"comment\":\"语速整体适中，但断句存在偏差，比如“孤舟蓑笠翁”部分没有正确断句，导致节奏不够准确。\",\"encourage\":\"多留意标准朗读的断句和语速，慢慢调整，你能把握好朗读的节奏感的！\"}]}','天山鸟飞绝\n万静陈宗业\n古咒说\n独钓寒江雪','2026-05-12 21:17:03',NULL),(1778593681595,'xiaoming','','',31,'池上',8,'{\"overallScore\":8,\"overallComment\":\"这次跟读内容有点偏离啦，不过能听出你读的几个字发音很清晰，下次看着原文逐字跟读，肯定会有很大进步的！\",\"dimensions\":[{\"name\":\"发音准确度\",\"score\":10,\"weight\":40,\"comment\":\"跟读内容与标准原文偏差较大，仅能判断读的“小王从小听”这几个字发音基本清晰，但未跟读指定的《池上》句子，准确度严重不足\",\"encourage\":\"下次可以看着原文逐字朗读，先把每个目标字的读音读准，你一定可以做到的！\"},{\"name\":\"语调模仿\",\"score\":5,\"weight\":25,\"comment\":\"因跟读内容完全偏离标准原文，无法体现对标准语音抑扬顿挫的模仿\",\"encourage\":\"后续跟读时可以先多听几遍标准语音的语调，再跟着慢慢模仿，逐步掌握语调的变化哦\"},{\"name\":\"流利度\",\"score\":10,\"weight\":20,\"comment\":\"读当前内容时较为流畅，但未跟读指定的原文句子，不符合跟读任务要求\",\"encourage\":\"只要看着原文逐字朗读，你一定能流畅地把《池上》的句子读出来的！\"},{\"name\":\"节奏感\",\"score\":5,\"weight\":15,\"comment\":\"跟读内容与原文不符，无法对应原文的语速和断句要求，难以体现节奏感\",\"encourage\":\"下次跟读可以跟着标准语音的节奏，慢慢调整自己的语速和断句，逐步跟上节奏哦\"}]}','小王从小听\n\n','2026-05-12 21:48:01',NULL),(1778636375141,'xiaoming','','',34,'江上渔者',7,'{\"overallScore\":7,\"overallComment\":\"你能准确读出开头的四个字已经很棒啦，这次可能有点分心，下次跟读时专注看着原文，跟着标准语音慢慢读，相信你会有很大的进步！\",\"dimensions\":[{\"name\":\"发音准确度\",\"score\":10,\"weight\":40,\"comment\":\"仅开头“江上往来人”四个字读音较为标准，后续内容完全偏离原文，大部分字音不符合要求\",\"encourage\":\"你能准确读出开头的四个字很棒，下次跟读时可以更专注地看着原文，逐字逐句读，相信你能把每个字的发音都读准！\"},{\"name\":\"语调模仿\",\"score\":5,\"weight\":25,\"comment\":\"仅开头部分有基本语调，后续内容语调混乱，未模仿标准语音的抑扬顿挫\",\"encourage\":\"开头的语调把握得不错，继续跟着标准语音的语调起伏来读，你会做得越来越好哦！\"},{\"name\":\"流利度\",\"score\":5,\"weight\":20,\"comment\":\"后