INSERT INTO `quiz_questions` VALUES (1779011125001,1779011125001,1,'“白日依山尽”中“尽”的意思是？','{\"A\":\"尽头\",\"B\":\"消失\",\"C\":\"全部\",\"D\":\"达到极限\"}',1,'“尽”在此处指太阳完全落下、消失于山后，描绘夕阳西下的景象。',1),(1779011125002,1779011125001,1,'“欲穷千里目”表达了诗人怎样的情感？','{\"A\":\"对远方风景的向往\",\"B\":\"对人生短暂的感慨\",\"C\":\"积极进取、追求更高境界\",\"D\":\"对黄河壮阔的赞美\"}',2,'诗句通过“更上一层楼”的意象，传达出诗人不断追求、开拓视野的进取精神。',2),(1779011125003,1779011125001,1,'《登鹳雀楼》的韵脚字是“流”和“楼”，属于押什么韵？','{\"A\":\"平声韵\",\"B\":\"仄声韵\",\"C\":\"入声韵\",\"D\":\"上声韵\"}',0,'“流”和“楼”均为平声字，属于平声韵，符合五言绝句的押韵规律。',3),(1779011125004,1779011125001,2,'“春眠不觉晓”中“晓”的意思是？','{\"A\":\"知道\",\"B\":\"天亮\",\"C\":\"早晨\",\"D\":\"明白\"}',1,'“晓”指天亮、清晨，诗句意为春夜睡眠不知不觉已到天亮。',4),(1779011125005,1779011125001,2,'“花落知多少”表达了诗人怎样的情感？','{\"A\":\"对花落的惋惜\",\"B\":\"对春天的喜爱\",\"C\":\"对风雨的抱怨\",\"D\":\"对时光流逝的无奈\"}',0,'诗人由风雨声联想到花落，流露出对春景易逝的怜惜之情。',5),(1779011125006,1779011125001,2,'《春晓》的体裁是？','{\"A\":\"五言绝句\",\"B\":\"七言绝句\",\"C\":\"五言律诗\",\"D\":\"古体诗\"}',0,'全诗四句，每句五字，符合五言绝句的格式。',6),(1779011125007,1779011125001,3,'“天似穹庐，笼盖四野”中“穹庐”指的是？','{\"A\":\"宫殿\",\"B\":\"帐篷\",\"C\":\"天空\",\"D\":\"山丘\"}',1,'“穹庐”是游牧民族居住的毡帐，即帐篷，这里比喻天空像帐篷一样笼罩大地。',7),(1779011125008,1779011125001,3,'“风吹草低见牛羊”中“见”的读音和意思是？','{\"A\":\"jiàn，看见\",\"B\":\"xiàn，出现\",\"C\":\"jiàn，见解\",\"D\":\"xiàn，现在\"}',1,'“见”通“现”，读xiàn，意为显现、出现，描绘风吹草动后牛羊显露的景象。',8),(1779011125009,1779011125001,3,'《敕勒歌》属于什么类型的诗歌？','{\"A\":\"田园诗\",\"B\":\"边塞诗\",\"C\":\"北朝民歌\",\"D\":\"送别诗\"}',2,'《敕勒歌》是北朝时期敕勒族的民歌，描绘草原风光，属于民歌范畴。',9),(1779011125010,1779011125001,3,'“天苍苍，野茫茫”中“苍苍”和“茫茫”共同营造了怎样的意境？','{\"A\":\"空旷辽远\",\"B\":\"阴郁压抑\",\"C\":\"生机勃勃\",\"D\":\"寂静无声\"}',0,'“苍苍”形容天空的青色辽阔，“茫茫”形容原野的无边无际，共同展现草原的壮阔景象。',10),(1779086097727,1779086097727,1,'“离离原上草”中“离离”的意思是？','{\"A\":\"形容草木茂盛\",\"B\":\"形容离别悲伤\",\"C\":\"形容稀疏零落\",\"D\":\"形容颜色青翠\"}',0,'“离离”在诗中指青草茂密繁盛的样子，描绘原野上野草的生机勃勃。',1),(1779086097728,1779086097727,1,'“野火烧不尽，春风吹又生”这两句诗主要表达了什么？','{\"A\":\"野草的生命力顽强\",\"B\":\"野火的无情与破坏\",\"C\":\"春天的温暖与希望\",\"D\":\"送别时的伤感与不舍\"}',0,'这两句通过野火烧不尽、春风再生，突出野草顽强的生命力，也隐含对友情的坚韧寄托。',2),(1779086097729,1779086097727,1,'《赋得古原草送别》是唐代诗人________的作品。','{}',30268,'这首诗是白居易的成名作，题目中的“赋得”是古代应制或命题作诗时的常用语。',3),(1779086097730,1779086097727,2,'“忽闻岸上踏歌声”中“踏歌”指的是？','{\"A\":\"边走边唱，以脚步打节拍\",\"B\":\"用脚踢踏乐器\",\"C\":\"骑马唱歌\",\"D\":\"在船上唱歌\"}',0,'“踏歌”是唐代民间的一种歌舞形式，众人手拉手，边踏地边唱歌，此处写汪伦以歌送别。',4),(1779086097731,1779086097727,2,'“桃花潭水深千尺，不及汪伦送我情”中运用了什么修辞手法？','{\"A\":\"比喻和夸张\",\"B\":\"拟人和对偶\",\"C\":\"排比和反问\",\"D\":\"设问和借代\"}',0,'“深千尺”是夸张，将友情比作潭水是比喻，以潭水之深反衬友情更深。',5),(1779086097732,1779086097727,2,'《赠汪伦》中，诗人李白在________（地名）乘舟离开。','{}',26626,'诗中的“桃花潭”位于今安徽泾县，是汪伦送别李白的地点。',6),(1779086097733,1779086097727,3,'“日照香炉生紫烟”中“香炉”指的是？','{\"A\":\"香炉峰\",\"B\":\"焚香的器具\",\"C\":\"寺庙中的香炉\",\"D\":\"一种植物\"}',0,'“香炉”指庐山的香炉峰，因形似香炉且常有云雾缭绕而得名。',7),(1779086097734,1779086097727,3,'“飞流直下三千尺”中的“三千尺”是实写还是虚写？','{\"A\":\"虚写，夸张瀑布的高\",\"B\":\"实写，精确测量\",\"C\":\"虚写，形容水流急\",\"D\":\"实写，指瀑布长度\"}',0,'“三千尺”是夸张手法，极言瀑布之高，并非实际长度，体现诗人浪漫的想象。',8),(1779086097735,1779086097727,3,'《望庐山瀑布》中，诗人将瀑布比作“银河落九天”，其中“九天”指________。','{}',22760,'“九天”在古文中常指极高的天空，此处形容瀑布仿佛从天上倾泻而下。',9),(1779086097736,1779086097727,3,'这首诗的格律属于？','{\"A\":\"七言绝句\",\"B\":\"五言绝句\",\"C\":\"七言律诗\",\"D\":\"五言律诗\"}',0,'《望庐山瀑布》共四句，每句七字，符合七言绝句的格式，押平声韵。',10),(1779086186391,1779086186391,1,'“忽闻岸上踏歌声”中“踏歌”的意思是？','{\"A\":\"用脚踏地打节拍唱歌\",\"B\":\"边跳舞边唱歌\",\"C\":\"在岸边走路唱歌\",\"D\":\"一种乐器演奏方式\"}',0,'“踏歌”是唐代民间的一种歌唱形式，以脚踏地为节拍，边踏边唱，故选A。',1),(1779086186392,1779086186391,1,'“桃花潭水深千尺”中“深千尺”运用的修辞手法是？','{\"A\":\"比喻\",\"B\":\"拟人\",\"C\":\"夸张\",\"D\":\"对偶\"}',2,'“深千尺”以夸张手法极言潭水之深，突出后文情感之深厚，故选C。',2),(1779086186393,1779086186391,1,'这首诗主要表达了诗人怎样的情感？','{\"A\":\"对桃花潭景色的赞美\",\"B\":\"对汪伦送别之情的感激和深厚友谊\",\"C\":\"对旅途的孤独和忧伤\",\"D\":\"对故乡的思念\"}',1,'诗中以“不及汪伦送我情”直接点明，用潭水之深反衬友情之厚，表达了对汪伦真挚情谊的感激。',3),(1779086186394,1779086186391,1,'本诗的韵脚字是？','{\"A\":\"行、声、情\",\"B\":\"欲、歌、深\",\"C\":\"行、歌、情\",\"D\":\"行、声、深\"}',0,'诗中“行”“声”“情”押韵，均为后鼻音韵母，属于平声韵，故选A。',4),(1779086186395,1779086186391,1,'李白被称为“诗仙”，其诗风主要特点是？','{\"A\":\"沉郁顿挫\",\"B\":\"豪放飘逸\",\"C\":\"婉约含蓄\",\"D\":\"清丽自然\"}',1,'李白诗风以豪放飘逸著称，想象丰富，语言奔放，本诗虽写送别却豁达深情，体现了这一特点。',5),(1779091759477,1779091759477,0,'“春眠不觉晓”中“晓”的意思是？','{\"A\":\"早晨\",\"B\":\"知道\",\"C\":\"天亮\",\"D\":\"明白\"}',0,'“晓”在此诗中指早晨，全句意为春夜睡眠不知不觉已到早晨。',1),(1779091759478,1779091759477,0,'“处处闻啼鸟”描绘了怎样的意境？','{\"A\":\"寂静无声的清晨\",\"B\":\"鸟鸣声此起彼伏的生机勃勃\",\"C\":\"鸟儿哭泣的悲伤\",\"D\":\"夜晚的宁静\"}',1,'“处处闻啼鸟”写到处听到鸟的啼叫声，展现春天清晨的活泼与生机。',2),(1779091759479,1779091759477,0,'诗中“夜来风雨声”后，诗人最可能的情感是？','{\"A\":\"对风雨的恐惧\",\"B\":\"对落花的惋惜\",\"C\":\"对春天的赞美\",\"D\":\"对夜晚的喜爱\"}',1,'诗人由风雨声联想到花落，表达了对春光易逝的淡淡惋惜之情。',3),(1779091759480,1779091759477,0,'这首诗的格律属于？','{\"A\":\"五言绝句\",\"B\":\"七言绝句\",\"C\":\"五言律诗\",\"D\":\"七言律诗\"}',0,'《春晓》每句五字，共四句，符合五言绝句的格律特征。',4),(1779091759481,1779091759477,0,'本诗作者孟浩然是哪个朝代的诗人？','{\"A\":\"宋代\",\"B\":\"唐代\",\"C\":\"明代\",\"D\":\"清代\"}',1,'孟浩然是唐代著名的山水田园派诗人，与王维并称“王孟”。',5),(1779108853761,1779108853761,1,'《江雪》中“绝”字的意思是？','{\"A\":\"断绝\",\"B\":\"绝妙\",\"C\":\"绝迹\",\"D\":\"绝对\"}',2,'“绝”在此处意为消失、绝迹，形容鸟飞尽，与“灭”呼应。',1),(1779108853762,1779108853761,1,'《江雪》中“孤舟蓑笠翁”一句，主要表达了诗人怎样的情感？','{\"A\":\"孤独寂寞\",\"B\":\"闲适自在\",\"C\":\"愤世嫉俗\",\"D\":\"乐观豁达\"}',0,'“孤舟”和“独钓”突出孤独感，结合诗人被贬背景，表达孤寂之情。',2),(1779108853763,1779108853761,1,'《江雪》中“千山鸟飞绝”的“千山”是实指一千座山吗？请判断。','{\"A\":\"是\",\"B\":\"否\"}',1,'“千山”是夸张手法，形容山之多，并非实指。',3),(1779108853764,1779108853761,1,'《江雪》的体裁是？','{\"A\":\"五言绝句\",\"B\":\"七言绝句\",\"C\":\"五言律诗\",\"D\":\"七言律诗\"}',0,'全诗四句，每句五字，符合五言绝句特征。',4),(1779108853765,1779108853761,2,'《村居》中“拂堤杨柳醉春烟”的“醉”字，运用的修辞手法是？','{\"A\":\"比喻\",\"B\":\"拟人\",\"C\":\"夸张\",\"D\":\"对偶\"}',1,'“醉”将杨柳拟人化，赋予其沉醉春烟的情态。',5),(1779108853766,1779108853761,2,'《村居》中“忙趁东风放纸鸢”的“纸鸢”指什么？','{\"A\":\"风筝\",\"B\":\"纸船\",\"C\":\"纸鹤\",\"D\":\"纸伞\"}',0,'“纸鸢”即风筝，古代以纸糊成鸢形放飞。',6),(1779108853767,1779108853761,2,'《村居》一诗主要描写的是哪个季节的景色？','{\"A\":\"春天\",\"B\":\"夏天\",\"C\":\"秋天\",\"D\":\"冬天\"}',0,'诗中“草长莺飞”“二月天”“春烟”均指向春季。',7),(1779108853768,1779108853761,2,'《村居》中“儿童散学归来早”的“散学”意思是？','{\"A\":\"放学\",\"B\":\"逃学\",\"C\":\"开学\",\"D\":\"辍学\"}',0,'“散学”指学校放学，与现代用法一致。',8),(1779108853769,1779108853761,3,'《赋得古原草送别》中“离离原上草”的“离离”形容什么？','{\"A\":\"茂盛的样子\",\"B\":\"稀疏的样子\",\"C\":\"分离的样子\",\"D\":\"枯萎的样子\"}',0,'“离离”形容草茂盛繁密，如“离离原上草”。',9),(1779108853770,1779108853761,3,'《赋得古原草送别》中“野火烧不尽”的“尽”字意思是？','{\"A\":\"完全\",\"B\":\"尽头\",\"C\":\"尽力\",\"D\":\"尽管\"}',0,'“尽”意为完全、彻底，强调野火无法完全烧毁草根。',10),(1779108853771,1779108853761,3,'《赋得古原草送别》中“一岁一枯荣”的“枯荣”指的是？','{\"A\":\"草的枯萎和茂盛\",\"B\":\"树木的干枯和繁荣\",\"C\":\"人的衰老和兴盛\",\"D\":\"季节的更替\"}',0,'“枯荣”特指草一年中枯萎与茂盛的循环。',11),(1779108853772,1779108853761,3,'《赋得古原草送别》中“春风吹又生”一句，表达了诗人怎样的情感？','{\"A\":\"对生命顽强的赞美\",\"B\":\"对离别的不舍\",\"C\":\"对春天的喜爱\",\"D\":\"对时光流逝的感慨\"}',0,'诗句通过草的重生，象征生命力的顽强，表达赞美之情。',12),(1779108853773,1779108853761,3,'《赋得古原草送别》的题目中“赋得”一词表明这首诗的创作方式是？','{\"A\":\"即兴赋诗\",\"B\":\"应考或应制之作\",\"C\":\"赠别友人\",\"D\":\"咏物抒怀\"}',1,'“赋得”是古代科举或应制诗中常见的题目格式，表示按指定题目作诗。',13);
