INSERT INTO `quiz_record` VALUES (1778645025446,'xiaoming','xiaoming',24,'静夜思',60,12,5,3,'[{\"question\":\"诗句“疑是地上霜”中“疑”字的意思是？\",\"options\":[\"怀疑\",\"好像\",\"疑问\",\"确定\"],\"answer\":1,\"analysis\":\"“疑”在这里表示“好像、仿佛”，诗人将月光比作霜，用“疑”字写出了月光洒在地上的错觉。\",\"selected\":0},{\"question\":\"诗句“举头望明月”中“举”字的意思是？\",\"options\":[\"举起\",\"抬起\",\"举起（重物）\",\"全部\"],\"answer\":1,\"analysis\":\"“举头”就是“抬头”的意思，“举”在此处表示“抬起”，而非“举起”或“举行”。\",\"selected\":0}]','2026-05-13 12:03:45'),(1778645070894,'xiaoming','小明',24,'静夜思',40,6,5,2,'[{\"question\":\"“举头望明月”中“举”的正确解释是？\",\"options\":[\"A. 抬起\",\"B. 放下\",\"C. 抛掷\",\"D. 全部\"],\"answer\":0,\"analysis\":\"“举头”即“抬头”，其中“举”指抬起、向上的动作。\",\"selected\":1},{\"question\":\"诗人为什么将月光“疑是地上霜”？\",\"options\":[\"A. 月光洁白如霜，颜色相似\",\"B. 天气寒冷，地面结霜\",\"C. 诗人视力模糊看错了\",\"D. 地上确实有霜\"],\"answer\":0,\"analysis\":\"诗句运用比喻，借月光与霜颜色相近的特点，表现月光的清冷洁白，并非真的下霜。\",\"selected\":2},{\"question\":\"这首诗主要表达了诗人怎样的情感？\",\"options\":[\"A. 对月亮的喜爱\",\"B. 对家乡的思念\",\"C. 对秋天的赞美\",\"D. 对孤独的逃避\"],\"answer\":1,\"analysis\":\"全诗以月光为引，通过“低头思故乡”直接点明主题，核心情感是身处异乡对故乡的深切思念。\",\"selected\":3}]','2026-05-13 12:04:30'),(1778645084798,'xiaoming','小明',24,'静夜思',20,6,5,1,'[{\"question\":\"“举头望明月”中“举”字的意思是？\",\"options\":[\"抬起\",\"举起\",\"全\",\"提出\"],\"answer\":0,\"analysis\":\"“举头”即抬头，“举”在这里是“抬起”的意思，描述诗人抬头看明月的动作。\",\"selected\":2},{\"question\":\"“床前明月光”一句描写了什么情景？\",\"options\":[\"床前洒满了明亮的月光\",\"床前有一盏灯发出月光\",\"床前的地面像霜一样白\",\"床前有明月和光\"],\"answer\":0,\"analysis\":\"诗句直接描写床前被明亮的月光照亮，是静夜中的常见景象。\",\"selected\":3},{\"question\":\"诗人为什么“低头思故乡”？\",\"options\":[\"因为看到明月，想起远方的家乡\",\"因为地上有霜，感到寒冷\",\"因为听到了思乡的歌声\",\"因为白天太累，低头休息\"],\"answer\":0,\"analysis\":\"诗人抬头望月，月光常引发思乡之情，故低头时思念故乡。\",\"selected\":2},{\"question\":\"这首诗主要表达了诗人怎样的情感？\",\"options\":[\"对秋天的喜爱\",\"对故乡的思念\",\"对明月的赞美\",\"对旅途的厌倦\"],\"answer\":1,\"analysis\":\"《静夜思》通过描写月夜景象，抒发了诗人客居他乡时对故乡深深的思念之情。\",\"selected\":2}]','2026-05-13 12:04:45'),(1778645102998,'xiaoming','小明',24,'静夜思',40,6,5,2,'[{\"question\":\"“疑是地上霜”中“疑”的正确解释是什么？\",\"options\":[\"A. 怀疑\",\"B. 好像\",\"C. 疑问\",\"D. 疑惑\"],\"answer\":1,\"analysis\":\"“疑”在此处是“好像”的意思，诗人将月光比作霜，并非真的怀疑。\",\"selected\":2},{\"question\":\"诗人“低头思故乡”的直接原因是什么？\",\"options\":[\"A. 看到月光想起故乡\",\"B. 看到霜想起故乡\",\"C. 听到声音想起故乡\",\"D. 看到床想起故乡\"],\"answer\":0,\"analysis\":\"诗人抬头望月，月光引发对故乡的思念，所以低头沉思，归乡之情油然而生。\",\"selected\":1},{\"question\":\"这首《静夜思》主要表达了诗人怎样的思想感情？\",\"options\":[\"A. 孤独和悲伤\",\"B. 思念故乡\",\"C. 对月亮的喜爱\",\"D. 对秋天的感慨\"],\"answer\":1,\"analysis\":\"全诗通过描写月光下静夜的景象，以“思故乡”点明主旨，表达了游子深切的思乡之情。\",\"selected\":2}]','2026-05-13 12:05:02'),(1778646443040,'xiaoming','xiaoming',26,'春晓',60,50,5,3,'[{\"question\":\"“春眠不觉晓”中“晓”的意思是？\",\"options\":[\"A. 早晨\",\"B. 知道\",\"C. 天亮\",\"D. 清楚\"],\"answer\":0,\"analysis\":\"“晓”在诗中指早晨，“不觉晓”即不知不觉天已亮了。\",\"selected\":2},{\"question\":\"“花落知多少”中“知”的意思是？\",\"options\":[\"A. 知道\",\"B. 知识\",\"C. 感觉\",\"D. 了解\"],\"answer\":0,\"analysis\":\"“知”在这里是“知道”的意思，诗人感叹花落了多少。\",\"selected\":1}]','2026-05-13 12:27:22'),(1778719959284,'xiaoming','xiaoming',0,'AI智能出题',20,15,10,2,'[{\"question\":\"《绝句》中“一行白鹭上青天”的朗读节奏划分正确的一项是？\",\"options\":[\"一行/白鹭/上青天\",\"一/行白鹭/上青天\",\"一行白/鹭上青天\",\"一行白鹭上/青天\"],\"answer\":0,\"analysis\":\"正确的节奏是“一行/白鹭/上青天”，这是五言绝句常见的二二一节奏。\",\"selected\":2},{\"question\":\"《清明》中“清明时节雨纷纷”的朗读节奏划分正确的一项是？\",\"options\":[\"清明/时节/雨纷纷\",\"清明时节/雨纷纷\",\"清/明时节/雨纷纷\",\"清明时节雨/纷纷\"],\"answer\":0,\"analysis\":\"七言绝句的常见节奏是二二二一或二二一二，此句正确为“清明/时节/雨纷纷”。\",\"selected\":1},{\"question\":\"《登鹳雀楼》中“欲穷千里目”的“穷”字读音正确的一项是？\",\"options\":[\"qióng\",\"qún\",\"qióng\",\"qíong\"],\"answer\":0,\"analysis\":\"\\\"穷\\\"的正确读音是qióng，意为尽、极。\",\"selected\":1},{\"question\":\"《画》中“远看山有色”的“色”字读音正确的一项是？\",\"options\":[\"sè\",\"shè\",\"sài\",\"shài\"],\"answer\":0,\"analysis\":\"\\\"色\\\"的正确读音是sè，意为颜色。\",\"selected\":1},{\"question\":\"《江雪》中“千山鸟飞绝”的“绝”字读音正确的一项是？\",\"options\":[\"jué\",\"jié\",\"juè\",\"jiě\"],\"answer\":0,\"analysis\":\"\\\"绝\\\"的正确读音是jué，意为尽、消失。\",\"selected\":1},{\"question\":\"《池上》中“小娃撑小艇”的“撑”字读音正确的一项是？\",\"options\":[\"chēng\",\"chèng\",\"chéng\",\"zhǎng\"],\"answer\":0,\"analysis\":\"\\\"撑\\\"的正确读音是chēng，意为用篙撑船。\",\"selected\":3},{\"question\":\"《江上渔者》中“江上往来人”的“往”字读音正确的一项是？\",\"options\":[\"wǎng\",\"wàng\",\"wán\",\"wǎn\"],\"answer\":0,\"analysis\":\"\\\"往\\\"的正确读音是wǎng，意为去、来往。\",\"selected\":2},{\"question\":\"《静夜思》中“床前明月光”的“床”字读音正确的一项是？\",\"options\":[\"chuáng\",\"cuáng\",\"chuāng\",\"zhuàng\"],\"answer\":0,\"analysis\":\"\\\"床\\\"的正确读音是chuáng，指坐卧的器具。\",\"selected\":1}]','2026-05-14 08:52:39'),(1778720266861,'xiaoming','xiaoming',0,'AI智能出题',20,17,10,2,'[{\"question\":\"《望庐山瀑布》和《山行》都描写了自然中的山景，下面哪一项对两首诗中山的意象理解正确？\",\"options\":[\"A. 《望庐山瀑布》的山是秀丽的，《山行》的山是险峻的\",\"B. 两首诗都描写了山的颜色，分别是紫色和白色\",\"C. 《望庐山瀑布》的山高耸入云，《山行》的山深远幽静\",\"D. 两首诗都没有直接写山，只写了山上的事物\"],\"answer\":2,\"analysis\":\"《望庐山瀑布》通过“日照香炉生紫烟”表现山的高耸，《山行》通过“远上寒山石径斜”表现山的深远幽静。\",\"selected\":1},{\"question\":\"在“疑是银河落九天”中，“疑”字的意思是？\",\"options\":[\"A. 怀疑\",\"B. 好像\",\"C. 疑问\",\"D. 不确定\"],\"answer\":1,\"analysis\":\"“疑”在此处意为“好像”，诗人把瀑布比作银河，用“疑是”表达恍若真实的惊叹。\",\"selected\":2},{\"question\":\"下列哪首诗的作者是唐代诗人？\",\"options\":[\"A. 《望庐山瀑布》—李白\",\"B. 《绝句》（两个黄鹂鸣翠柳）—杜甫\",\"C. 《山行》—杜牧\",\"D. 以上都是\"],\"answer\":3,\"analysis\":\"李白、杜甫、杜牧均为唐代诗人。\",\"selected\":2},{\"question\":\"《绝句》（两个黄鹂鸣翠柳）和《山行》最后两句分别表达了诗人怎样的情感？\",\"options\":[\"A. 都是对自然美景的喜爱\",\"B. 《绝句》是思乡之情，《山行》是闲适之情\",\"C. 《绝句》是喜悦之情，《山行》是悲秋之情\",\"D. 《绝句》是赞美春景，《山行》是赞美秋景\"],\"answer\":3,\"analysis\":\"《绝句》以“窗含西岭千秋雪”等句展现明媚春景，表达赞美；《山行》以“霜叶红于二月花”赞美秋景，两诗意境不同但都表达对自然景色的欣赏。\",\"selected\":1},{\"question\":\"下面诗句中，哪一项中的“行”字与“一行白鹭上青天”的“行”意思相同？\",\"options\":[\"A. 山行\",\"B. 行到水穷处\",\"C. 队列之行\",\"D. 行走\"],\"answer\":2,\"analysis\":\"“一行白鹭”的“行”是量词，指成排的队伍，“队列之行”中的“行”也是量词。“山行”的“行”是行走。\",\"selected\":1},{\"question\":\"从诵读节奏看，五言诗句通常采用什么节奏？下面哪一句诗句属于五言？\",\"options\":[\"A. 日照香炉生紫烟\",\"B. 两个黄鹂鸣翠柳\",\"C. 停车坐爱枫林晚\",\"D. 以上都不是五言\"],\"answer\":3,\"analysis\":\"三个选项均为七言诗句，五言应为“迟日江山丽”这样的句式。\",\"selected\":1},{\"question\":\"《望庐山瀑布》与《山行》都运用了比喻修辞手法，下面哪一项说法正确？\",\"options\":[\"A. 《望庐山瀑布》把瀑布比作银河，《山行》把枫叶比作花\",\"B. 《望庐山瀑布》把香炉峰比作烟，《山行》把寒山比作斜\",\"C. 两首诗都没有比喻\",\"D. 《望庐山瀑布》把瀑布比作烟，《山行》把枫叶比作火\"],\"answer\":0,\"analysis\":\"“飞流直下三千尺，疑是银河落九天”将瀑布比作银河；“霜叶红于二月花”将枫叶比作二月花。\",\"selected\":1},{\"question\":\"下面关于三首诗文学常识的叙述，哪一项错误？\",\"options\":[\"A. 《望庐山瀑布》的作者李白被称为“诗仙”\",\"B. 《绝句》的作者杜甫被称为“诗圣”\",\"C. 《山行》的作者杜牧生活在晚唐\",\"D. 三首诗都是五言绝句\"],\"answer\":3,\"analysis\":\"三首诗都是七言绝句，不是五言绝句。\",\"selected\":2}]','2026-05-14 08:57:47'),(1778721112894,'xiaoming','xiaoming',0,'AI智能出题',40,22,10,4,'[{\"question\":\"《悯农（其二）》中“锄禾日当午”的正确断句是？\",\"options\":[\"锄禾/日当午\",\"锄/禾日当午\",\"锄禾日/当午\",\"锄禾日当/午\"],\"answer\":0,\"analysis\":\"五言诗句通常为“二三”节奏，“锄禾/日当午”符合古诗朗读习惯。\",\"selected\":1},{\"question\":\"《清明》中“清明时节雨纷纷”的下一句是？\",\"options\":[\"路上行人欲断魂\",\"牧童遥指杏花村\",\"借问酒家何处有\",\"夜来风雨声\"],\"answer\":0,\"analysis\":\"《清明》首句为“清明时节雨纷纷”，次句为“路上行人欲断魂”。\",\"selected\":1},{\"question\":\"《登鹳雀楼》中“白日依山尽”的“尽”读音是？\",\"options\":[\"jìn\",\"jǐn\",\"jīn\",\"jìng\"],\"answer\":0,\"analysis\":\"“尽”在此处意为消失，读jìn，声调为第四声。\",\"selected\":1},{\"question\":\"《画》中“远看山有色”的下一句是？\",\"options\":[\"近听水无声\",\"春去花还在\",\"人来鸟不惊\",\"白毛浮绿水\"],\"answer\":0,\"analysis\":\"《画》首句为“远看山有色”，次句为“近听水无声”。\",\"selected\":2},{\"question\":\"《江雪》中“千山鸟飞绝”的正确断句是？\",\"options\":[\"千山/鸟飞绝\",\"千/山鸟飞绝\",\"千山鸟/飞绝\",\"千山鸟飞/绝\"],\"answer\":0,\"analysis\":\"五言诗句常见“二三”节奏，“千山/鸟飞绝”符合古诗朗读习惯。\",\"selected\":2},{\"question\":\"《池上》中“小娃撑小艇”的下一句是？\",\"options\":[\"偷采白莲回\",\"不解藏踪迹\",\"浮萍一道开\",\"粒粒皆辛苦\"],\"answer\":0,\"analysis\":\"《池上》首句为“小娃撑小艇”，次句为“偷采白莲回”。\",\"selected\":1}]','2026-05-14 09:11:53'),(1778721210858,'xiaoming','xiaoming',0,'AI智能出题',10,12,10,1,'[{\"question\":\"下列对《望庐山瀑布》与《题西林壁》的诵读节奏划分，正确的一项是？\",\"options\":[\"A. 日照/香炉/生紫烟，横看/成岭/侧成峰\",\"B. 日照香炉/生紫烟，横看成岭/侧成峰\",\"C. 日照/香炉生/紫烟，横看/成岭侧/成峰\",\"D. 日照香炉生/紫烟，横看成岭侧/成峰\"],\"answer\":0,\"analysis\":\"《望庐山瀑布》首句节奏为“日照/香炉/生紫烟”，《题西林壁》首句为“横看/成岭/侧成峰”，均为二二一结构。\",\"selected\":2},{\"question\":\"“飞流直下三千尺”中“直下”的意思是？\",\"options\":[\"A. 笔直地落下\",\"B. 直接下去\",\"C. 一直向下\",\"D. 立刻下去\"],\"answer\":0,\"analysis\":\"“直下”指瀑布垂直倾泻，突出其气势磅礴，与“飞流”呼应。\",\"selected\":1},{\"question\":\"《题西林壁》中“不识庐山真面目”的“识”解释为？\",\"options\":[\"A. 认识\",\"B. 记住\",\"C. 辨别\",\"D. 知道\"],\"answer\":0,\"analysis\":\"“识”在此处意为“认识、看清”，强调因身处山中而无法看清全貌。\",\"selected\":1},{\"question\":\"下列哪项是《望庐山瀑布》与《题西林壁》的共同文学常识？\",\"options\":[\"A. 均为唐代诗人所作\",\"B. 均描写庐山景色\",\"C. 均采用七言绝句形式\",\"D. 均表达思乡之情\"],\"answer\":1,\"analysis\":\"两首诗均以庐山为题材，但《望庐山瀑布》为李白作（唐），《题西林壁》为苏轼作（宋），体裁上均为七言绝句，但主题不同。\",\"selected\":0},{\"question\":\"两首诗在情感表达上的主要区别是？\",\"options\":[\"A. 《望庐山瀑布》赞美自然，《题西林壁》抒发哲理\",\"B. 均表达对庐山的喜爱\",\"C. 《望庐山瀑布》写实，《题西林壁》写虚\",\"D. 均表达人生感慨\"],\"answer\":0,\"analysis\":\"李白通过夸张手法赞美瀑布的壮美，苏轼则借庐山阐述“当局者迷”的哲理。\",\"selected\":1},{\"question\":\"“疑是银河落九天”中“九天”指？\",\"options\":[\"A. 九重天，形容极高\",\"B. 九天的意思\",\"C. 天空\",\"D. 宇宙\"],\"answer\":0,\"analysis\":\"“九天”是古代传说中天的最高层，此处夸张地形容瀑布如银河从天而降。\",\"selected\":2},{\"question\":\"下列对两首诗节奏的表述，错误的是？\",\"options\":[\"A. 《望庐山瀑布》为二二三节奏\",\"B. 《题西林壁》为二二一二节奏\",\"C. 两首诗均为七言绝句\",\"D. 两首诗节奏均工整\"],\"answer\":1,\"analysis\":\"七言绝句通常为二二三或四三节奏，《题西林壁》首句“横看/成岭/侧成峰”为二二一节奏，后三字“侧成峰”为二一结构。\",\"selected\":3},{\"question\":\"“只缘身在此山中”的“缘”意思是？\",\"options\":[\"A. 因为\",\"B. 缘分\",\"C. 沿着\",\"D. 原因\"],\"answer\":0,\"analysis\":\"“缘”在此处意为“因为”，全句解释为何不识庐山真面目。\",\"selected\":3},{\"question\":\"两首诗共同体现的创作手法是？\",\"options\":[\"A. 比喻与夸张\",\"B. 借景抒情\",\"C. 对比与衬托\",\"D. 托物言志\"],\"answer\":1,\"analysis\":\"两首诗均通过描写庐山景色来抒发情感或阐述道理，属于借景抒情手法。\",\"selected\":0}]','2026-05-14 09:13:30'),(1778751351645,'xiaoming','小明',5,'悯农（其二）',20,14,5,1,'[{\"question\":\"“锄禾日当午”中“当”字的意思是？\",\"options\":[\"A. 应当\",\"B. 正在\",\"C. 面对\",\"D. 阻挡\"],\"answer\":1,\"analysis\":\"“当”在此处意为“正在”，指中午时分，农民在烈日下劳作。\",\"selected\":0},{\"question\":\"“汗滴禾下土”中“禾”指的是？\",\"options\":[\"A. 禾苗\",\"B. 树木\",\"C. 杂草\",\"D. 花朵\"],\"answer\":0,\"analysis\":\"“禾”指禾苗，即庄稼的幼苗，与农耕相关。\",\"selected\":1},{\"question\":\"“谁知盘中餐”这句诗表达了什么？\",\"options\":[\"A. 饭菜很美味\",\"B. 人们知道粮食的来历\",\"C. 很少有人了解粮食的艰辛\",\"D. 盘子中的食物很多\"],\"answer\":2,\"analysis\":\"“谁知”意为“有谁知道”，反问语气，强调很少有人真正体会粮食的来之不易。\",\"selected\":0},{\"question\":\"“粒粒皆辛苦”中的“皆”意思是？\",\"options\":[\"A. 都是\",\"B. 只有\",\"C. 可能\",\"D. 偶尔\"],\"answer\":0,\"analysis\":\"“皆”意为“都、全部”，强调每一粒粮食都凝结了农民的辛苦。\",\"selected\":2}]','2026-05-14 17:35:51'),(1778771457824,'xiaoming','xiaoming',0,'AI智能出题',20,40,10,2,'[{\"question\":\"《悯农（其二）》中\'谁知盘中餐\'表达了什么情感？\",\"options\":[\"对粮食的珍惜\",\"对农夫的同情\",\"对丰收的喜悦\",\"对自然的赞美\"],\"answer\":1,\"analysis\":\"此句如溪水轻诉，道出农夫辛劳，粒粒皆辛苦，令人心生怜惜。\",\"selected\":0},{\"question\":\"《清明》中\'清明时节雨纷纷\'的断句是？\",\"options\":[\"清明/时节/雨纷纷\",\"清明时/节雨/纷纷\",\"清明时节/雨纷纷\",\"清明/时节雨/纷纷\"],\"answer\":0,\"analysis\":\"如柳枝轻摇，\'清明\'为节名，\'时节\'为时间，\'雨纷纷\'为景象，自然断句。\",\"selected\":3},{\"question\":\"《登鹳雀楼》中\'欲穷千里目\'的\'穷\'字读音是？\",\"options\":[\"qióng\",\"qóng\",\"qǒng\",\"qòng\"],\"answer\":0,\"analysis\":\"\'穷\'意为尽，读第二声，如登楼望远，目极天涯。\",\"selected\":1},{\"question\":\"《画》中\'远看山有色\'的\'色\'字读音是？\",\"options\":[\"sè\",\"shè\",\"sě\",\"sè（轻声）\"],\"answer\":0,\"analysis\":\"\'色\'指颜色，读第四声，如远山青翠，近水无声。\",\"selected\":2},{\"question\":\"《江雪》中\'千山鸟飞绝\'的断句是？\",\"options\":[\"千山/鸟飞绝\",\"千/山鸟/飞绝\",\"千山鸟/飞绝\",\"千山鸟飞/绝\"],\"answer\":0,\"analysis\":\"如雪落无声，\'千山\'为景，\'鸟飞绝\'为事，自然断开。\",\"selected\":2},{\"question\":\"《池上》中\'小娃撑小艇\'的\'艇\'字读音是？\",\"options\":[\"tǐng\",\"tíng\",\"tìng\",\"tǐng（轻声）\"],\"answer\":0,\"analysis\":\"\'艇\'指小船，读第三声，如小娃撑舟，轻划池上。\",\"selected\":2},{\"question\":\"《江上渔者》中\'江上往来人\'的断句是？\",\"options\":[\"江上/往来人\",\"江/上往来/人\",\"江上往/来人\",\"江上往来人/\"],\"answer\":0,\"analysis\":\"如江水悠悠，\'江上\'为地点，\'往来人\'为人物，自然断句。\",\"selected\":1},{\"question\":\"《静夜思》中\'床前明月光\'的意境是什么？\",\"options\":[\"月光如霜，思乡之情\",\"月光如雪，寒冷孤寂\",\"月光如水，宁静祥和\",\"月光如银，富贵华丽\"],\"answer\":0,\"analysis\":\"此句如月照窗前，霜白似雪，诗人举头望月，低头思乡，意境清冷而深情。\",\"selected\":2}]','2026-05-14 23:10:58'),(1778919295815,'xiaoming','小明',5,'悯农（其二）',60,34,5,3,'[{\"question\":\"“锄禾日当午”中“当”的意思是？\",\"options\":[\"A. 应当\",\"B. 正在\",\"C. 当做\",\"D. 阻挡\"],\"answer\":1,\"analysis\":\"“当”在此处是“正在”的意思，指正午时分，农民在烈日下锄地。\",\"selected\":0},{\"question\":\"“谁知盘中餐，粒粒皆辛苦”这两句诗的意思是？\",\"options\":[\"A. 谁知道盘子里的饭菜，每一粒都包含了辛苦\",\"B. 谁知道盘子里的饭菜，每一粒都很辛苦\",\"C. 谁知道盘子里的饭菜，每一粒都很好吃\",\"D. 谁知道盘子里的饭菜，每一粒都很珍贵\"],\"answer\":0,\"analysis\":\"诗句直译为：有谁知道盘子里的饭食，每一粒都凝聚着农民的辛苦？强调粮食来之不易。\",\"selected\":3}]','2026-05-16 16:14:56'),(1778922543446,'xiaohong','小红',43,'赠汪伦',100,29,5,5,'[]','2026-05-16 17:09:03'),(1778922592249,'xiaohong','小红',51,'梅花',20,11,5,1,'[{\"question\":\"“凌寒独自开”中“凌”的意思是？\",\"options\":[\"A. 欺凌\",\"B. 冒着\",\"C. 超过\",\"D. 结冰\"],\"answer\":1,\"analysis\":\"“凌”在此处意为“冒着”，指梅花在严寒中独自开放，表现其不畏寒冷的精神。\",\"selected\":2},{\"question\":\"诗句“墙角数枝梅，凌寒独自开”描写了梅花怎样的特点？\",\"options\":[\"A. 鲜艳夺目\",\"B. 不畏严寒\",\"C. 生长茂盛\",\"D. 香气浓郁\"],\"answer\":1,\"analysis\":\"诗句突出梅花在墙角独自开放，不惧严寒，体现了其坚强、孤傲的特点。\",\"selected\":3},{\"question\":\"“为有暗香来”中“暗香”指的是？\",\"options\":[\"A. 夜晚的香气\",\"B. 隐约的香气\",\"C. 强烈的香气\",\"D. 雪的气味\"],\"answer\":1,\"analysis\":\"“暗香”指梅花散发出的清淡、隐约的香气，不是浓烈刺鼻的味道。\",\"selected\":2},{\"question\":\"这首诗通过描写梅花，主要表达了诗人怎样的情感？\",\"options\":[\"A. 对雪景的喜爱\",\"B. 对春天到来的期盼\",\"C. 对高洁品格的赞美\",\"D. 对孤独生活的哀叹\"],\"answer\":2,\"analysis\":\"诗人借梅花不畏严寒、独自开放的形象，赞美了高洁、坚贞的品格，表达了对这种精神的向往。\",\"selected\":1}]','2026-05-16 17:09:51'),(1778922743195,'xiaoming','xiaoming',7,'江雪',20,12,5,1,'[{\"question\":\"诗句“千山鸟飞绝”中“绝”字的意思是？\",\"options\":[\"A. 断绝\",\"B. 消失，无踪影\",\"C. 绝对\",\"D. 走不通\"],\"answer\":1,\"analysis\":\"“绝”在此处表示消失、没有踪迹，形容山中鸟儿都飞走了，不见踪影。\",\"selected\":0},{\"question\":\"诗句“万径人踪灭”中“径”字的意思是？\",\"options\":[\"A. 直径\",\"B. 小路\",\"C. 经过\",\"D. 径直\"],\"answer\":1,\"analysis\":\"“径”指小路，“万径”即千万条小路，形容路上没有行人踪迹。\",\"selected\":0},{\"question\":\"对“孤舟蓑笠翁”的理解，正确的一项是？\",\"options\":[\"A. 一只孤独的小船上，坐着一位穿着蓑衣、戴着斗笠的老翁\",\"B. 孤独的小船和蓑衣、斗笠的老人\",\"C. 一位老翁在船上穿着蓑衣、戴着斗笠\",\"D. 小船和蓑笠老人一起\"],\"answer\":0,\"analysis\":\"诗句描绘了一幅画面：一只孤独的小船，船上有一位身披蓑衣、头戴斗笠的老翁。选项A最准确。\",\"selected\":1},{\"question\":\"这首诗表达了诗人怎样的情感？\",\"options\":[\"A. 对雪景的喜爱和赞美\",\"B. 孤独、清高和坚贞不屈的情操\",\"C. 对渔翁生活的羡慕\",\"D. 对家乡的思念\"],\"answer\":1,\"analysis\":\"柳宗元被贬永州后创作此诗，借寒江独钓的渔翁形象，表达自己孤独、清高和不与世俗同流合污的坚贞品质。\",\"selected\":2}]','2026-05-16 17:12:23'),(1778923060021,'xiaoming','xiaoming',5,'悯农（其二）',40,11,5,2,'[{\"question\":\"“汗滴禾下土”中“滴”字的意思是？\",\"options\":[\"A. 滴落\",\"B. 水滴\",\"C. 一滴\",\"D. 滴答\"],\"answer\":0,\"analysis\":\"“滴”在这里是动词，意为滴落，描绘汗水从农民身上滴到土地上的情景。\",\"selected\":1},{\"question\":\"“谁知盘中餐”一句中“餐”指的是什么？\",\"options\":[\"A. 早餐\",\"B. 饭菜\",\"C. 餐厅\",\"D. 餐具\"],\"answer\":1,\"analysis\":\"“餐”在诗中泛指饭菜，指盘中的食物，强调粮食的来之不易。\",\"selected\":0},{\"question\":\"诗句“粒粒皆辛苦”表达的主要意思是？\",\"options\":[\"A. 每一粒粮食都饱含农民的辛苦\",\"B. 每一粒粮食都很好吃\",\"C. 每一粒粮食都很珍贵\",\"D. 每一粒粮食都很重\"],\"answer\":0,\"analysis\":\"“粒粒皆辛苦”直接点明每一粒粮食都凝聚着农民的辛勤劳动，是诗的核心思想。\",\"selected\":1}]','2026-05-16 17:17:39'),(1778923385565,'xiaohong','小红',82,'清平乐·村居',80,36,5,4,'[{\"question\":\"下列对“大儿锄豆溪东”的理解，正确的一项是？\",\"options\":[\"A. 大儿子在溪东锄地种豆\",\"B. 大儿子在溪东锄草种豆\",\"C. 大儿子在溪东锄地除草，豆子已种下\",\"D. 大儿子在溪东用锄头挖豆子\"],\"answer\":2,\"analysis\":\"“锄豆”指在豆田里锄草，而非种豆或挖豆，诗句描写大儿子在溪东的豆田里劳作，锄去杂草。\",\"selected\":1}]','2026-05-16 17:23:05'),(1778925148590,'xiaohong','xiaohong',0,'AI智能出题',30,159,10,3,'[{\"question\":\"《山行》中“停车坐爱枫林晚”的“坐”字，与《枫桥夜泊》中“江枫渔火对愁眠”的“对”字，在表达情感上的共同点是？\",\"options\":[\"A. 都表现闲适愉悦\",\"B. 都表现孤独愁绪\",\"C. 都表现羁旅漂泊\",\"D. 都表现归隐之志\"],\"answer\":1,\"analysis\":\"《山行》的“坐”意为“因为”，诗人因喜爱枫林而停车，但结合全诗“寒山”“石径”等意象，暗含孤寂；《枫桥夜泊》的“对”字直接展现客船中诗人与江枫渔火相对的孤独愁绪。两字均强化了诗人的孤寂感。\",\"selected\":0},{\"question\":\"《山行》中的“枫林”与《枫桥夜泊》中的“江枫”，在诗歌中共同承载的意象内涵是？\",\"options\":[\"A. 象征坚贞爱情\",\"B. 代表离别之情\",\"C. 暗示时光易逝\",\"D. 寄托隐逸情怀\"],\"answer\":2,\"analysis\":\"枫叶经霜变红，常被用来象征季节更替和时光流逝。《山行》中“霜叶红于二月花”暗含秋景虽美但短暂；《枫桥夜泊》中“江枫”与“愁眠”结合，强化了漂泊中时光流逝的感伤。\",\"selected\":1},{\"question\":\"《山行》与《枫桥夜泊》都描写了秋夜或秋景，但两诗在整体意境上的主要区别是？\",\"options\":[\"A. 前者热烈后者凄清\",\"B. 前者静谧后者喧闹\",\"C. 前者欢快后者忧伤\",\"D. 前者空灵后者沉重\"],\"answer\":0,\"analysis\":\"《山行》以“霜叶红于二月花”收尾，色彩明丽，意境热烈而生机勃勃；《枫桥夜泊》以“夜半钟声到客船”作结，钟声清冷，意境凄清孤寂。\",\"selected\":2},{\"question\":\"《山行》中“白云生处有人家”的“人家”，与《枫桥夜泊》中“姑苏城外寒山寺”的“寺”，在诗歌中的共同作用是？\",\"options\":[\"A. 作为景物点缀\",\"B. 暗示社会背景\",\"C. 寄托归隐理想\",\"D. 引发时空联想\"],\"answer\":3,\"analysis\":\"“人家”隐于白云深处，引发对山居生活的遐想；“寺”位于城外，钟声穿越时空，引发对历史与现实的思考。两处都通过空间或时间的延伸，拓展了诗歌的意境。\",\"selected\":2},{\"question\":\"《山行》中“停车坐爱枫林晚”的“晚”字，与《枫桥夜泊》中“月落乌啼霜满天”的“落”字，在时间意象上的共同点是？\",\"options\":[\"A. 暗示白昼将尽\",\"B. 象征生命终结\",\"C. 突出夜晚静谧\",\"D. 强调季节变迁\"],\"answer\":0,\"analysis\":\"“晚”字点明傍晚时分，天色渐暗；“落”字写月落，暗示黎明前最黑暗的时刻。两字都指向一天中光线暗淡的时段，营造出朦胧或孤寂的氛围。\",\"selected\":1},{\"question\":\"《山行》中的“石径”与《枫桥夜泊》中的“客船”，在诗歌中共同承载的意象内涵是？\",\"options\":[\"A. 象征人生道路\",\"B. 代表漂泊无依\",\"C. 暗示归隐之志\",\"D. 突出旅途艰辛\"],\"answer\":1,\"analysis\":\"“石径”蜿蜒于寒山，暗示诗人独行山中的漂泊感；“客船”直接点明诗人羁旅在外、无依无靠的处境。两意象都强化了漂泊无依的主题。\",\"selected\":0},{\"question\":\"《山行》与《枫桥夜泊》在结尾手法上的共同特点是？\",\"options\":[\"A. 以景结情，余韵悠长\",\"B. 直抒胸臆，情感强烈\",\"C. 设问收束，引人深思\",\"D. 对比收尾，突出主题\"],\"answer\":0,\"analysis\":\"《山行》以“霜叶红于二月花”的景色收尾，情感蕴含其中；《枫桥夜泊》以“夜半钟声到客船”的钟声作结，愁绪弥漫。两诗都通过景物描写间接表达情感，留下想象空间。\",\"selected\":1}]','2026-05-16 17:52:28'),(1778925217588,'xiaohong','小红',0,'AI智能出题',100,27,10,10,'[]','2026-05-16 17:53:37'),(1779012608706,'xiaohong','xiaohong',5,'悯农（其二）',20,8,5,1,'[{\"question\":\"“锄禾日当午”中的“当”是什么意思？\",\"options\":[\"A. 应当\",\"B. 正对着\",\"C. 当作\",\"D. 阻挡\"],\"answer\":1,\"analysis\":\"“当”在这里是“正对着”的意思，形容中午太阳正对着地面，强调时间炎热。\",\"selected\":0},{\"question\":\"“粒粒皆辛苦”中的“皆”是什么意思？\",\"options\":[\"A. 全部\",\"B. 都是\",\"C. 一样\",\"D. 同时\"],\"answer\":0,\"analysis\":\"“皆”意为“全部、都”，表示每一粒粮食都来之不易。\",\"selected\":1},{\"question\":\"“谁知盘中餐，粒粒皆辛苦”这两句诗想告诉我们什么？\",\"options\":[\"A. 粮食很好吃\",\"B. 粮食很便宜\",\"C. 每一粒粮食都来之不易，要珍惜\",\"D. 农民很辛苦，但不用在意\"],\"answer\":2,\"analysis\":\"这两句诗通过反问强调粮食的来之不易，告诫人们要珍惜劳动成果。\",\"selected\":0},{\"question\":\"这首诗表达了诗人怎样的情感？\",\"options\":[\"A. 对农民劳动的赞美和同情\",\"B. 对粮食的喜爱\",\"C. 对天气炎热的抱怨\",\"D. 对田园生活的向往\"],\"answer\":0,\"analysis\":\"全诗通过描写农民锄禾的艰辛，表达了诗人对农民辛勤劳动的深切同情和对劳动成果的尊重。\",\"selected\":2}]','2026-05-17 18:10:09'),(1779020758981,'xiaoming','小明',25,'登鹳雀楼',40,10,5,2,'[{\"question\":\"“欲穷千里目”中“穷”的意思是？\",\"options\":[\"A. 贫穷\",\"B. 穷尽\",\"C. 困境\",\"D. 彻底\"],\"answer\":1,\"analysis\":\"“穷”在此处意为“穷尽”，即看尽千里之外的景色，表达极目远眺的愿望，因此选B。\",\"selected\":0},{\"question\":\"“黄河入海流”描绘的景象是？\",\"options\":[\"A. 黄河水流入大海，流向远方\",\"B. 黄河水在海上流动\",\"C. 黄河与海相连，形成河流\",\"D. 黄河水倒流入海\"],\"answer\":0,\"analysis\":\"诗句描写黄河奔腾东流，最终汇入大海的壮阔景象，因此选A。\",\"selected\":2},{\"question\":\"“欲穷千里目，更上一层楼”这两句诗的意思是？\",\"options\":[\"A. 想要看到更远的景色，需要登上更高的楼\",\"B. 为了看到千里之外，必须努力上楼\",\"C. 只有登上楼顶，才能看到远处的河海\",\"D. 眼睛想看远处，需要多上几层楼\"],\"answer\":0,\"analysis\":\"诗句表达了只有站得高才能看得远的哲理，即想要极目远眺，就需要再登上一层楼，因此选A。\",\"selected\":2}]','2026-05-17 20:25:59'),(1779020994656,'xiaoming','小明',0,'AI智能出题',20,63,10,2,'[{\"question\":\"《悯农（其二）》中“谁知盘中餐”的“餐”字读音是？\",\"options\":[\"cān\",\"chān\",\"cāng\",\"chāng\"],\"answer\":0,\"analysis\":\"“餐”读作cān，指饭食，诗句强调粮食来之不易。\",\"selected\":2},{\"question\":\"《悯农（其二）》中“锄禾日当午”描绘了怎样的劳动场景？\",\"options\":[\"农民在中午烈日下锄草\",\"农民在清晨播种\",\"农民在傍晚收割\",\"农民在雨天施肥\"],\"answer\":0,\"analysis\":\"诗句写农民在正午烈日下锄草，汗滴入土，体现劳动的艰辛。\",\"selected\":2},{\"question\":\"《清明》中“清明时节雨纷纷”的“纷”字读音是？\",\"options\":[\"fēn\",\"fēng\",\"fěn\",\"fèng\"],\"answer\":0,\"analysis\":\"“纷”读作fēn，形容雨多而杂乱，渲染清明哀愁氛围。\",\"selected\":3},{\"question\":\"《江雪》中“孤舟蓑笠翁”的“蓑”字读音是？\",\"options\":[\"suō\",\"shuō\",\"suǒ\",\"shuò\"],\"answer\":0,\"analysis\":\"“蓑”读作suō，指草编的雨衣，描绘渔翁雪中独钓的孤寂。\",\"selected\":2},{\"question\":\"《江雪》中“独钓寒江雪”表达了诗人怎样的心境？\",\"options\":[\"孤独清高\",\"热闹欢快\",\"愤怒不平\",\"悠闲自在\"],\"answer\":0,\"analysis\":\"诗句通过寒江独钓的意象，寄托诗人柳宗元被贬后的孤傲与坚韧。\",\"selected\":3},{\"question\":\"《静夜思》中“床前明月光”的“床”字读音是？\",\"options\":[\"chuáng\",\"chuàng\",\"chuān\",\"chuǎng\"],\"answer\":0,\"analysis\":\"“床”读作chuáng，指坐卧的家具，诗句写月光洒在床前。\",\"selected\":2},{\"question\":\"《静夜思》中“举头望明月”表达了诗人怎样的情感？\",\"options\":[\"思乡之情\",\"喜悦之情\",\"愤怒之情\",\"离别之情\"],\"answer\":0,\"analysis\":\"诗人抬头望月，引发对故乡的思念，体现游子的乡愁。\",\"selected\":3},{\"question\":\"《春晓》中“春眠不觉晓”描绘了怎样的意境？\",\"options\":[\"春夜酣睡，不觉天亮\",\"春天早起，精神抖擞\",\"春夜失眠，辗转反侧\",\"春天寒冷，难以入眠\"],\"answer\":0,\"analysis\":\"诗句写春夜睡得香甜，不知不觉天已亮，体现春日的慵懒与美好。\",\"selected\":2}]','2026-05-17 20:29:54'),(1779021121173,'xiaoming','小明',26,'春晓',20,40,5,1,'[{\"question\":\"“春眠不觉晓”中“晓”的意思是？\",\"options\":[\"A. 早晨\",\"B. 知道\",\"C. 天亮\",\"D. 小\"],\"answer\":0,\"analysis\":\"“晓”在古诗中常指早晨或天亮，结合“春眠不觉晓”，意为春夜睡眠不知不觉已到早晨，故选A。\",\"selected\":1},{\"question\":\"“花落知多少”中“知”的意思是？\",\"options\":[\"A. 知道\",\"B. 不知\",\"C. 了解\",\"D. 估计\"],\"answer\":1,\"analysis\":\"“知多少”在诗中为反问语气，实际表达“不知多少”，强调花落之多，故“知”应理解为“不知”，选B。\",\"selected\":2},{\"question\":\"“夜来风雨声，花落知多少”表达了诗人怎样的心情？\",\"options\":[\"A. 对风雨的喜爱\",\"B. 对花落的惋惜\",\"C. 对春天的赞美\",\"D. 对夜晚的恐惧\"],\"answer\":1,\"analysis\":\"诗人由昨夜风雨联想到花瓣飘落，用“知多少”的疑问表达对落花的怜惜和春天易逝的淡淡哀愁，故选B。\",\"selected\":0},{\"question\":\"《春晓》一诗最可能表达了诗人怎样的情感？\",\"options\":[\"A. 对春天的热爱和珍惜\",\"B. 对夏天的期待\",\"C. 对秋天的伤感\",\"D. 对冬天的怀念\"],\"answer\":0,\"analysis\":\"《春晓》通过描写春晨鸟鸣和昨夜风雨后的落花，既展现春天的生机，又流露对春光易逝的珍惜之情，故选A。\",\"selected\":2}]','2026-05-17 20:32:00');
