DROP TABLE IF EXISTS `recitationtask`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `recitationtask` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `addtime` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `studentaccount` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户账号',
  `studentname` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户姓名',
  `courseids` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '背诵古诗ID集合',
  `coursetitles` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '背诵古诗标题集合',
  `tasktitle` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '任务标题',
  `taskcontent` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '任务要求',
  `deadline` datetime DEFAULT NULL COMMENT '截止日期',
  `completionstatus` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT '待完成' COMMENT '完成状态',
  `completionremark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '完成说明',
  `recitationaudio` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '背诵音频',
  `completiontime` datetime DEFAULT NULL COMMENT '完成时间',
  `kaoshichengji` int DEFAULT NULL COMMENT '背诵得分',
  `teachercomment` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '教师评语',
  `teacheraccount` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '教师账号',
  `teachername` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '教师姓名',
  `releasetime` datetime DEFAULT NULL COMMENT '发布日期',
  `recognizedtext` longtext COLLATE utf8mb4_general_ci COMMENT '识别文本',
  `aiscorecomment` longtext COLLATE utf8mb4_general_ci COMMENT 'AI评分评语',
  `task_type` int DEFAULT '1' COMMENT '1语音背诵2AI测验',
  `classname` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1779108877749 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='背诵任务';
