  `studentname` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '用户姓名',
  `avatar` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci COMMENT '头像',
  `gender` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '性别',
  `telephone` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '手机号码',
  `grade` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '年级',
  `classname` varchar(200) COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '班级',
  `medalcount` int DEFAULT '0' COMMENT '勋章数量',
  `permissionstatus` varchar(200) COLLATE utf8mb4_general_ci DEFAULT '启用' COMMENT '权限状态',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `studentaccount` (`studentaccount`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1779087970629 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='用户';
